window.__qzParts=window.__qzParts||{};window.__qzParts.vatly=[{"p":"Một vật chuyển động thẳng đều. Vận tốc của vật được xác định bằng công thức nào?","o":["v = s · t","v = t / s","v = s / t","v = s² / t"],"a":"v = s / t","h":"Vận tốc cho biết quãng đường đi được trong một đơn vị thời gian.","e":"Trong chuyển động thẳng đều, vận tốc v = s / t và không đổi theo thời gian.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Một ô tô chuyển động thẳng đều, đi được quãng đường 180 km trong 3 giờ. Vận tốc của ô tô là:","o":["540 km/h","60 km/h","30 km/h","90 km/h"],"a":"60 km/h","h":"Lấy quãng đường chia cho thời gian chuyển động.","e":"v = s / t = 180 / 3 = 60 km/h.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Một xe máy tăng tốc từ 5 m/s lên 15 m/s trong 2 s. Gia tốc của xe là:","o":["5 m/s²","10 m/s²","7,5 m/s²","2,5 m/s²"],"a":"5 m/s²","h":"Dùng công thức a = (v − v₀) / t.","e":"a = (15 − 5) / 2 = 5 m/s².","t":"ly-lop10","g":10,"l":"thu-thach"},{"p":"Trên đồ thị vận tốc – thời gian, đồ thị là một đoạn thẳng song song với trục thời gian. Chuyển động đó là:","o":["chuyển động thẳng nhanh dần đều","chuyển động rơi tự do","chuyển động thẳng chậm dần đều","chuyển động thẳng đều"],"a":"chuyển động thẳng đều","h":"Đoạn thẳng song song trục thời gian nghĩa là vận tốc không thay đổi.","e":"Vận tốc giữ nguyên không đổi theo thời gian nên đó là chuyển động thẳng đều.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Trên đồ thị vận tốc – thời gian của một chuyển động thẳng, diện tích hình giới hạn bởi đồ thị và trục thời gian cho biết:","o":["gia tốc của vật","độ dịch chuyển của vật","lực tác dụng lên vật","khối lượng của vật"],"a":"độ dịch chuyển của vật","h":"Nhớ ý nghĩa hình học của diện tích dưới đồ thị v – t.","e":"Diện tích dưới đồ thị vận tốc – thời gian bằng độ dịch chuyển của vật trong khoảng thời gian đó.","t":"ly-lop10","g":10,"l":"thu-thach"},{"p":"Một vật được thả rơi tự do, lấy g ≈ 10 m/s², bỏ qua sức cản không khí. Quãng đường vật rơi được sau 2 s là:","o":["10 m","40 m","20 m","5 m"],"a":"20 m","h":"Dùng công thức h = ½gt² với vận tốc ban đầu bằng 0.","e":"h = ½ · 10 · 2² = 20 m.","t":"ly-lop10","g":10,"l":"thu-thach"},{"p":"Thả rơi tự do một vật từ độ cao 45 m, lấy g ≈ 10 m/s², bỏ qua sức cản không khí. Vận tốc của vật ngay khi chạm đất là:","o":["30 m/s","15 m/s","45 m/s","20 m/s"],"a":"30 m/s","h":"Tìm thời gian rơi từ h = ½gt² rồi tính v = gt.","e":"Thời gian rơi t = √(2h/g) = √(2 · 45 / 10) = 3 s, nên v = gt = 10 · 3 = 30 m/s.","t":"ly-lop10","g":10,"l":"thu-thach"},{"p":"Đo chiều dài một vật 3 lần được các kết quả 10,1 cm; 10,2 cm; 10,0 cm. Giá trị trung bình của phép đo là:","o":["10,0 cm","10,1 cm","10,2 cm","10,3 cm"],"a":"10,1 cm","h":"Cộng ba kết quả đo rồi chia cho 3.","e":"(10,1 + 10,2 + 10,0) / 3 = 30,3 / 3 = 10,1 cm.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Một học sinh chạy thẳng đều với vận tốc 4 m/s. Quãng đường em chạy được sau 5 s là:","o":["0,8 m","9 m","1,25 m","20 m"],"a":"20 m","h":"Dùng công thức s = v · t.","e":"s = 4 · 5 = 20 m.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Một vật chuyển động thẳng biến đổi đều có gia tốc 2 m/s². Điều đó có nghĩa là:","o":["mỗi giây vật đi được 2 m","vận tốc của vật luôn bằng 2 m/s","mỗi giây vận tốc của vật tăng thêm 2 m/s","vật đi được quãng đường 2 m trong giây đầu tiên"],"a":"mỗi giây vận tốc của vật tăng thêm 2 m/s","h":"Gia tốc cho biết độ thay đổi vận tốc trong một giây.","e":"Gia tốc là độ biến thiên vận tốc trong một đơn vị thời gian: sau mỗi giây, vận tốc thay đổi 2 m/s.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Theo định luật I Newton, một vật đang đứng yên sẽ tiếp tục đứng yên khi:","o":["không có lực tác dụng lên vật hoặc hợp lực tác dụng lên vật bằng 0","có một lực kéo không đổi tác dụng lên vật","vật chỉ chịu tác dụng của trọng lực","vật chịu lực ma sát rất lớn"],"a":"không có lực tác dụng lên vật hoặc hợp lực tác dụng lên vật bằng 0","h":"Nhớ tính quán tính của vật khi hợp lực bằng 0.","e":"Khi hợp lực bằng 0, vật giữ nguyên trạng thái đứng yên hoặc chuyển động thẳng đều — đó là nội dung định luật I Newton.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Một lực 20 N tác dụng lên vật có khối lượng 4 kg, bỏ qua ma sát. Gia tốc của vật là:","o":["80 m/s²","0,2 m/s²","24 m/s²","5 m/s²"],"a":"5 m/s²","h":"Dùng định luật II Newton: a = F / m.","e":"a = F / m = 20 / 4 = 5 m/s².","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Theo định luật III Newton, cặp lực hành động và phản hành động có đặc điểm nào sau đây?","o":["Cùng đặt lên một vật","Cùng độ lớn, ngược chiều và đặt lên hai vật khác nhau","Cùng chiều và cùng độ lớn","Cân bằng nhau nên triệt tiêu lẫn nhau"],"a":"Cùng độ lớn, ngược chiều và đặt lên hai vật khác nhau","h":"Chú ý điểm đặt của hai lực trong cặp hành động – phản hành động.","e":"Hai lực hành động và phản hành động luôn cùng độ lớn, ngược chiều nhưng đặt lên hai vật khác nhau nên không triệt tiêu nhau.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Một vật có khối lượng 5 kg. Lấy g = 10 m/s². Trọng lượng của vật là:","o":["5 N","0,5 N","500 N","50 N"],"a":"50 N","h":"Dùng công thức trọng lượng P = m · g.","e":"P = m · g = 5 · 10 = 50 N.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Trọng lực tác dụng lên một vật có điểm đặt và phương như thế nào?","o":["Đặt tại trọng tâm của vật, phương thẳng đứng, chiều hướng về tâm Trái Đất","Đặt tại bề mặt tiếp xúc, phương nằm ngang","Đặt tại trọng tâm của vật, phương nằm ngang","Đặt tại điểm tiếp xúc với mặt đất, chiều hướng lên trên"],"a":"Đặt tại trọng tâm của vật, phương thẳng đứng, chiều hướng về tâm Trái Đất","h":"Trọng lực là lực hút của Trái Đất tác dụng lên vật.","e":"Trọng lực đặt tại trọng tâm của vật, có phương thẳng đứng và chiều hướng về tâm Trái Đất.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Khi kéo một thùng hàng trượt trên sàn nhà, cách làm nào sau đây giúp giảm lực ma sát trượt hiệu quả?","o":["Tăng diện tích mặt tiếp xúc của thùng với sàn","Đặt thêm vật nặng lên trên thùng","Làm đáy thùng thô ráp hơn","Lót các con lăn dưới thùng hoặc bôi trơn bề mặt tiếp xúc"],"a":"Lót các con lăn dưới thùng hoặc bôi trơn bề mặt tiếp xúc","h":"Lực ma sát trượt phụ thuộc vào áp lực và tính chất bề mặt tiếp xúc.","e":"Con lăn biến ma sát trượt thành ma sát lăn nhỏ hơn nhiều, và bôi trơn làm giảm ma sát; trong khi tăng áp lực hay độ nhám đều làm ma sát tăng.","t":"ly-lop10","g":10,"l":"thu-thach"},{"p":"Một vật có khối lượng 10 kg trượt trên mặt sàn nằm ngang với hệ số ma sát trượt 0,2. Lấy g = 10 m/s². Lực ma sát trượt tác dụng lên vật là:","o":["2 N","20 N","200 N","10 N"],"a":"20 N","h":"Tính áp lực N = m · g trước, rồi dùng F = μ · N.","e":"N = m · g = 10 · 10 = 100 N; F = μ · N = 0,2 · 100 = 20 N.","t":"ly-lop10","g":10,"l":"thu-thach"},{"p":"Người đi bộ được trên mặt đất là nhờ loại lực ma sát nào giữa bàn chân và mặt đất?","o":["Ma sát lăn","Ma sát trượt","Ma sát nghỉ","Lực đàn hồi"],"a":"Ma sát nghỉ","h":"Bàn chân không trượt trên mặt đất khi bước đi.","e":"Ma sát nghỉ giữa đế giày và mặt đất giữ cho chân không bị trượt và đẩy người về phía trước.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Một lò xo có độ cứng k = 100 N/m. Khi treo vật, lò xo giãn ra 0,05 m. Lực đàn hồi của lò xo là:","o":["5 N","2000 N","0,5 N","105 N"],"a":"5 N","h":"Dùng định luật Hooke: F = k · Δl.","e":"F = k · Δl = 100 · 0,05 = 5 N.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Một lực 10 N làm một lò xo giãn ra 2 cm. Độ cứng của lò xo là:","o":["20 N/m","0,2 N/m","5 N/m","500 N/m"],"a":"500 N/m","h":"Đổi 2 cm = 0,02 m rồi dùng k = F / Δl.","e":"k = F / Δl = 10 / 0,02 = 500 N/m.","t":"ly-lop10","g":10,"l":"thu-thach"},{"p":"Một vật khối lượng 2 kg chuyển động tròn đều với tốc độ 4 m/s trên quỹ đạo có bán kính 2 m. Độ lớn lực hướng tâm tác dụng lên vật là:","o":["4 N","8 N","16 N","32 N"],"a":"16 N","h":"Dùng công thức F = m · v² / r.","e":"F = m · v² / r = 2 · 4² / 2 = 16 N.","t":"ly-lop10","g":10,"l":"thu-thach"},{"p":"Hai lực đồng quy có độ lớn 6 N và 8 N, vuông góc với nhau. Hợp lực của chúng có độ lớn là:","o":["14 N","10 N","2 N","48 N"],"a":"10 N","h":"Hợp lực là cạnh huyền của tam giác vuông tạo bởi hai lực.","e":"F = √(6² + 8²) = √(36 + 64) = √100 = 10 N.","t":"ly-lop10","g":10,"l":"thu-thach"},{"p":"Một lực 50 N đẩy một vật đi được quãng đường 4 m theo hướng của lực. Công của lực là:","o":["200 J","12,5 J","54 J","0 J"],"a":"200 J","h":"Dùng công thức A = F · s khi lực cùng hướng chuyển động.","e":"A = F · s = 50 · 4 = 200 J.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Một máy thực hiện công 600 J trong 30 s. Công suất của máy là:","o":["18000 W","630 W","20 W","0,05 W"],"a":"20 W","h":"Dùng công thức công suất P = A / t.","e":"P = A / t = 600 / 30 = 20 W.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Một vật có khối lượng 2 kg đang chuyển động với vận tốc 3 m/s. Động năng của vật là:","o":["6 J","3 J","18 J","9 J"],"a":"9 J","h":"Dùng công thức động năng Wđ = ½mv².","e":"Wđ = ½ · 2 · 3² = 9 J.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Nếu vận tốc của một vật tăng gấp đôi, khối lượng không đổi, thì động năng của vật:","o":["tăng gấp 2 lần","tăng gấp 4 lần","không thay đổi","giảm đi một nửa"],"a":"tăng gấp 4 lần","h":"Động năng tỉ lệ với bình phương vận tốc.","e":"Wđ = ½mv²: vận tốc tăng 2 lần thì v² tăng 4 lần nên động năng tăng gấp 4 lần.","t":"ly-lop10","g":10,"l":"thu-thach"},{"p":"Một vật có khối lượng 2 kg ở độ cao 5 m so với mặt đất. Lấy g = 10 m/s², mốc thế năng tại mặt đất. Thế năng trọng trường của vật là:","o":["100 J","10 J","40 J","7 J"],"a":"100 J","h":"Dùng công thức thế năng Wt = m · g · h.","e":"Wt = m · g · h = 2 · 10 · 5 = 100 J.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Một vật rơi tự do từ độ cao h, bỏ qua sức cản không khí. Trong quá trình rơi:","o":["thế năng tăng, động năng giảm","cơ năng của vật tăng dần","thế năng giảm, động năng tăng, cơ năng không đổi","cơ năng của vật giảm dần"],"a":"thế năng giảm, động năng tăng, cơ năng không đổi","h":"Khi chỉ có trọng lực sinh công, cơ năng được bảo toàn.","e":"Khi rơi, độ cao giảm nên thế năng giảm; vận tốc tăng nên động năng tăng; tổng cơ năng giữ nguyên vì bỏ qua sức cản.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Thả rơi một vật từ độ cao 5 m, bỏ qua sức cản không khí, lấy g = 10 m/s². Áp dụng định luật bảo toàn cơ năng, vận tốc của vật ngay khi chạm đất là:","o":["5 m/s","50 m/s","25 m/s","10 m/s"],"a":"10 m/s","h":"Tại mặt đất thế năng bằng 0, toàn bộ thế năng ban đầu chuyển thành động năng: mgh = ½mv².","e":"v = √(2gh) = √(2 · 10 · 5) = √100 = 10 m/s.","t":"ly-lop10","g":10,"l":"thu-thach"},{"p":"Một vật có khối lượng 3 kg chuyển động với vận tốc 4 m/s. Động lượng của vật là:","o":["7 kg·m/s","12 kg·m/s","0,75 kg·m/s","24 kg·m/s"],"a":"12 kg·m/s","h":"Dùng công thức động lượng p = m · v.","e":"p = m · v = 3 · 4 = 12 kg·m/s.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Một vật 2 kg chuyển động với vận tốc 6 m/s, va chạm mềm vào một vật 4 kg đang đứng yên rồi dính vào nhau. Vận tốc của hai vật sau va chạm là:","o":["2 m/s","3 m/s","6 m/s","1 m/s"],"a":"2 m/s","h":"Áp dụng bảo toàn động lượng: m₁v₁ = (m₁ + m₂) · v.","e":"v = (2 · 6) / (2 + 4) = 12 / 6 = 2 m/s.","t":"ly-lop10","g":10,"l":"thu-thach"},{"p":"Biến dạng nào sau đây là biến dạng đàn hồi?","o":["Nặn một cục đất sét thành hình con vật","Uốn một thanh thép quá mức khiến nó cong vĩnh viễn","Kéo giãn một lò xo trong giới hạn cho phép rồi buông ra, lò xo trở lại độ dài ban đầu","Bẻ gãy một que gỗ"],"a":"Kéo giãn một lò xo trong giới hạn cho phép rồi buông ra, lò xo trở lại độ dài ban đầu","h":"Biến dạng đàn hồi là biến dạng mất đi khi thôi tác dụng lực.","e":"Lò xo trở lại hình dạng ban đầu sau khi thôi tác dụng lực nên đó là biến dạng đàn hồi.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Vật nào sau đây bị biến dạng dẻo sau khi thôi tác dụng lực?","o":["Lò xo bị kéo giãn nhẹ","Quả bóng cao su bị ấn nhẹ","Dây thun bị kéo giãn nhẹ","Miếng đất sét bị nặn thành hình mới"],"a":"Miếng đất sét bị nặn thành hình mới","h":"Biến dạng dẻo vẫn còn lại sau khi thôi tác dụng lực.","e":"Đất sét giữ nguyên hình dạng mới sau khi nặn, không tự trở lại hình dạng cũ nên đó là biến dạng dẻo.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Một học sinh kéo một lò xo bằng lực ngày càng lớn. Sau khi buông tay, lò xo không trở lại độ dài ban đầu nữa. Kết luận nào đúng?","o":["Lò xo bị biến dạng do nhiệt độ quá cao","Lực kéo đã vượt quá giới hạn đàn hồi của lò xo","Định luật Hooke đúng với mọi trường hợp kéo lò xo","Lò xo đã bị biến dạng đàn hồi hoàn toàn"],"a":"Lực kéo đã vượt quá giới hạn đàn hồi của lò xo","h":"Khi vượt một giới hạn nhất định, vật rắn không còn phục hồi hình dạng ban đầu.","e":"Khi lực tác dụng vượt quá giới hạn đàn hồi, vật bị biến dạng dẻo và không trở lại hình dạng ban đầu; định luật Hooke chỉ đúng trong giới hạn đàn hồi.","t":"ly-lop10","g":10,"l":"thu-thach"},{"p":"Việc làm nào sau đây an toàn khi sử dụng điện trong phòng thí nghiệm và trong đời sống?","o":["Ngắt cầu dao (aptomat) trước khi sửa chữa thiết bị điện","Dùng tay ướt để cắm phích điện vào ổ cắm","Chạm tay vào dây điện bị hở lớp cách điện","Cắm chung nhiều thiết bị công suất lớn vào cùng một ổ cắm"],"a":"Ngắt cầu dao (aptomat) trước khi sửa chữa thiết bị điện","h":"Luôn cắt nguồn điện trước khi sửa chữa và tránh để tay ướt tiếp xúc với điện.","e":"Ngắt cầu dao trước khi sửa chữa giúp tránh bị điện giật; tay ướt, dây điện hở và quá tải ổ cắm đều rất nguy hiểm.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Một học sinh đo chiều dài của một cây bút được kết quả l = 15,0 cm với sai số tuyệt đối Δl = 0,3 cm. Sai số tương đối của phép đo này là:","o":["0,2%","2%","20%","5%"],"a":"2%","h":"Sai số tương đối bằng tỉ số giữa sai số tuyệt đối và giá trị đo được, thường tính theo phần trăm.","e":"Sai số tương đối δl = Δl / l × 100% = 0,3 / 15,0 × 100% = 2%.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Việc làm nào sau đây tuân thủ đúng quy tắc an toàn trong phòng thực hành Vật lí?","o":["Cắm điện ngay để kiểm tra mạch mà không cần quan sát trước","Dùng tay còn ướt để cắm và rút phích điện","Chỉ đóng điện sau khi đã lắp mạch đúng sơ đồ và được giáo viên kiểm tra, cho phép","Mang đồ ăn, thức uống vào bàn thí nghiệm cho tiện"],"a":"Chỉ đóng điện sau khi đã lắp mạch đúng sơ đồ và được giáo viên kiểm tra, cho phép","h":"Nhớ nguyên tắc: mọi thao tác với điện và thiết bị chỉ thực hiện khi đã kiểm tra và được hướng dẫn.","e":"Theo quy tắc an toàn phòng thực hành, học sinh chỉ được đóng điện khi mạch đã lắp đúng sơ đồ và được giáo viên kiểm tra, cho phép. Đóng điện tùy tiện, dùng tay ướt chạm thiết bị điện hay ăn uống trong phòng thực hành đều nguy hiểm và bị cấm.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Trong hệ đơn vị quốc tế SI, đơn vị của cường độ dòng điện là:","o":["vôn (V)","ampe (A)","ôm (Ω)","oát (W)"],"a":"ampe (A)","h":"Hệ SI có 7 đơn vị cơ bản, trong đó có đơn vị đo dòng điện mang tên nhà vật lí Ampère.","e":"Ampe (A) là một trong 7 đơn vị cơ bản của hệ SI, dùng để đo cường độ dòng điện. Vôn, ôm, oát là các đơn vị dẫn xuất.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Một vận động viên chạy đúng một vòng quanh một sân vận động có chu vi 400 m rồi dừng lại tại đúng điểm xuất phát. Quãng đường vận động viên đã chạy và độ lớn độ dịch chuyển của vận động viên lần lượt là:","o":["400 m và 0 m","0 m và 400 m","400 m và 400 m","200 m và 0 m"],"a":"400 m và 0 m","h":"Quãng đường là độ dài đường đi; độ dịch chuyển chỉ phụ thuộc điểm đầu và điểm cuối.","e":"Quãng đường bằng chu vi đường chạy: 400 m. Vì điểm cuối trùng điểm đầu nên độ dịch chuyển bằng 0 m.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Đồ thị độ dịch chuyển – thời gian của một vật chuyển động thẳng là một đường thẳng đi qua gốc tọa độ và điểm có tọa độ (4 s; 20 m). Vận tốc của vật là:","o":["80 m/s","0,2 m/s","4 m/s","5 m/s"],"a":"5 m/s","h":"Trên đồ thị độ dịch chuyển – thời gian, vận tốc bằng độ dốc (hệ số góc) của đồ thị.","e":"Vận tốc v = Δd / Δt = 20 / 4 = 5 m/s. Đây cũng chính là độ dốc của đường thẳng trên đồ thị.","t":"ly-lop10","g":10,"l":"thu-thach"},{"p":"Một vật được ném ngang từ độ cao h so với mặt đất với vận tốc đầu v₀. Bỏ qua sức cản của không khí, quỹ đạo của vật là một phần của đường parabol. Thời gian từ lúc ném đến lúc vật chạm đất phụ thuộc vào:","o":["vận tốc ném v₀ và độ cao h","chỉ độ cao h (và gia tốc trọng trường g)","khối lượng của vật","chỉ vận tốc ném v₀"],"a":"chỉ độ cao h (và gia tốc trọng trường g)","h":"Trong chuyển động ném ngang, chuyển động theo phương thẳng đứng chính là rơi tự do từ độ cao h.","e":"Theo phương thẳng đứng, vật rơi tự do nên thời gian rơi t = √(2h/g), chỉ phụ thuộc vào h và g, không phụ thuộc vận tốc ném v₀ hay khối lượng của vật.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Để vặn chặt một bu lông, người ta dùng cờ lê có cánh tay đòn (khoảng cách từ trục quay đến đường tác dụng của lực) là 25 cm và tác dụng một lực 20 N vuông góc với cờ lê. Moment của lực đối với trục quay là:","o":["5 N·m","80 N·m","500 N·m","0,8 N·m"],"a":"5 N·m","h":"Moment lực M = F·d, chú ý đổi cánh tay đòn sang mét.","e":"Đổi d = 25 cm = 0,25 m. Moment lực M = F·d = 20 × 0,25 = 5 N·m.","t":"ly-lop10","g":10,"l":"thu-thach"},{"p":"Một vật có khối lượng 2 kg được treo đứng yên vào một sợi dây mảnh (bỏ qua khối lượng của dây). Lấy g ≈ 10 m/s². Lực căng của sợi dây là:","o":["2 N","200 N","10 N","20 N"],"a":"20 N","h":"Vật đứng yên nên lực căng dây cân bằng với trọng lượng của vật.","e":"Vật đứng yên, hợp lực tác dụng lên vật bằng 0 nên lực căng dây T bằng trọng lượng P = mg = 2 × 10 = 20 N.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Một hòn bi thép rơi trong nước chậm hơn hẳn so với khi rơi trong không khí, chủ yếu là vì:","o":["trọng lực tác dụng lên hòn bi trong nước nhỏ đi nhiều","khối lượng của hòn bi giảm khi ở trong nước","nước tác dụng lên hòn bi lực cản và lực nâng lớn hơn không khí rất nhiều","trong nước không có lực hấp dẫn"],"a":"nước tác dụng lên hòn bi lực cản và lực nâng lớn hơn không khí rất nhiều","h":"Ngoài trọng lực, khi chuyển động trong chất lỏng, vật còn chịu thêm những lực nào của môi trường?","e":"Khi rơi trong nước, ngoài trọng lực không đổi, hòn bi còn chịu lực cản của nước và lực đẩy (lực nâng) của nước hướng lên, lớn hơn trong không khí rất nhiều, nên hợp lực hướng xuống nhỏ đi và bi rơi chậm hơn.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Một động cơ điện nhận vào năng lượng 1 000 J và sinh ra công có ích 750 J (phần còn lại bị hao phí). Hiệu suất của động cơ là:","o":["133%","25%","7,5%","75%"],"a":"75%","h":"Hiệu suất bằng tỉ số giữa công có ích và năng lượng toàn phần nhận vào.","e":"Hiệu suất H = A_có ích / A_toàn phần × 100% = 750 / 1 000 × 100% = 75%.","t":"ly-lop10","g":10,"l":"thu-thach"},{"p":"Một lực không đổi 50 N tác dụng lên một vật trong khoảng thời gian 0,2 s. Độ biến thiên động lượng của vật trong khoảng thời gian đó là:","o":["10 kg·m/s","250 kg·m/s","100 kg·m/s","5 kg·m/s"],"a":"10 kg·m/s","h":"Dùng mối liên hệ giữa xung lượng của lực và độ biến thiên động lượng: F·Δt = Δp.","e":"Độ biến thiên động lượng Δp = F·Δt = 50 × 0,2 = 10 kg·m/s.","t":"ly-lop10","g":10,"l":"thu-thach"},{"p":"Một khẩu súng có khối lượng 4 kg (chưa kể đạn) bắn ra một viên đạn có khối lượng 20 g với vận tốc 500 m/s theo phương ngang. Bỏ qua ma sát, vận tốc giật lùi của súng ngay sau khi bắn là:","o":["25 m/s","2,5 m/s","0,25 m/s","10 m/s"],"a":"2,5 m/s","h":"Hệ súng – đạn là hệ kín nên động lượng được bảo toàn: động lượng của súng sau khi bắn có độ lớn bằng động lượng của đạn.","e":"Đổi m_đạn = 20 g = 0,02 kg. Bảo toàn động lượng: M·V = m·v, suy ra V = (0,02 × 500) / 4 = 10 / 4 = 2,5 m/s.","t":"ly-lop10","g":10,"l":"thu-thach"},{"p":"Một điểm trên vành bánh xe đang chuyển động tròn đều với tốc độ dài 8 m/s trên quỹ đạo có bán kính 2 m. Tốc độ góc của điểm đó là:","o":["16 rad/s","0,25 rad/s","4 rad/s","2 rad/s"],"a":"4 rad/s","h":"Tốc độ góc liên hệ với tốc độ dài qua công thức ω = v / r.","e":"Tốc độ góc ω = v / r = 8 / 2 = 4 rad/s.","t":"ly-lop10","g":10,"l":"thu-thach"},{"p":"Một vật chuyển động tròn đều với tốc độ 6 m/s trên quỹ đạo tròn có bán kính 3 m. Gia tốc hướng tâm của vật có độ lớn là:","o":["2 m/s²","12 m/s²","108 m/s²","18 m/s²"],"a":"12 m/s²","h":"Gia tốc hướng tâm a = v² / r.","e":"Gia tốc hướng tâm a = v² / r = 6² / 3 = 36 / 3 = 12 m/s².","t":"ly-lop10","g":10,"l":"thu-thach"},{"p":"Một khối kim loại có khối lượng 540 g và thể tích 200 cm³. Khối lượng riêng của kim loại này là:","o":["0,37 g/cm³","108 000 g/cm³","2,7 kg/cm³","2,7 g/cm³"],"a":"2,7 g/cm³","h":"Khối lượng riêng ρ = m / V.","e":"Khối lượng riêng ρ = m / V = 540 / 200 = 2,7 g/cm³ (tức 2 700 kg/m³, đúng bằng khối lượng riêng của nhôm).","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Lấy khối lượng riêng của nước là 1 000 kg/m³ và g ≈ 10 m/s². Áp suất do cột nước gây ra tại một điểm ở độ sâu 2 m dưới mặt thoáng của một hồ nước là:","o":["20 000 Pa","2 000 Pa","200 Pa","200 000 Pa"],"a":"20 000 Pa","h":"Áp suất chất lỏng ở độ sâu h: p = ρ·g·h.","e":"Áp suất do cột nước gây ra p = ρgh = 1 000 × 10 × 2 = 20 000 Pa. Đây là phần áp suất do riêng cột nước, chưa kể áp suất khí quyển tác dụng trên mặt thoáng.","t":"ly-lop10","g":10,"l":"thu-thach"},{"p":"Vật lí học là môn học như thế nào?","o":["Là môn học chỉ nghiên cứu về các con số và phép tính trừu tượng","Là môn khoa học tự nhiên nghiên cứu về vật chất, năng lượng và sự tương tác giữa chúng, làm cơ sở cho nhiều ngành khoa học và công nghệ khác","Là môn học chỉ nghiên cứu về lịch sử các phát minh nổi tiếng","Là môn học chỉ phục vụ cho việc chế tạo vũ khí"],"a":"Là môn khoa học tự nhiên nghiên cứu về vật chất, năng lượng và sự tương tác giữa chúng, làm cơ sở cho nhiều ngành khoa học và công nghệ khác","h":"Hãy nghĩ xem các thiết bị như điện thoại, máy chụp X-quang, động cơ... dựa trên kiến thức của môn học nào.","e":"Vật lí học là môn khoa học nghiên cứu các dạng vận động cơ bản nhất của vật chất (cơ, nhiệt, điện, từ, quang, hạt nhân) và năng lượng. Hiểu biết vật lí là nền tảng của kĩ thuật và công nghệ: điện, điện tử, cơ khí, xây dựng, y học...","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Máy bay có thể cất cánh và bay lên được chủ yếu nhờ lực nào sau đây?","o":["Lực ma sát giữa bánh xe máy bay và đường băng","Lực nâng của không khí tác dụng lên cánh máy bay","Lực hút của Trái Đất tác dụng lên máy bay","Lực đẩy của không khí về phía sau máy bay"],"a":"Lực nâng của không khí tác dụng lên cánh máy bay","h":"Hãy nghĩ đến hình dạng cong của cánh máy bay và dòng không khí chuyển động quanh cánh.","e":"Khi máy bay chuyển động, do hình dạng đặc biệt của cánh, không khí phía trên cánh chuyển động nhanh hơn phía dưới, tạo ra lực nâng hướng từ dưới lên. Khi lực nâng lớn hơn trọng lượng, máy bay cất cánh được. Đây là nội dung của Bài 19: Lực cản và lực nâng.","t":"ly-lop10","g":10,"l":"thu-thach"},{"p":"Một vật trượt không ma sát từ đỉnh một mặt phẳng nghiêng góc 30° so với phương ngang. Lấy g ≈ 10 m/s². Gia tốc của vật khi trượt xuống là bao nhiêu?","o":["5 m/s²","10 m/s²","2,5 m/s²","8,7 m/s²"],"a":"5 m/s²","h":"Hãy phân tích trọng lực thành thành phần song song với mặt phẳng nghiêng: a = g·sinα.","e":"Phân tích trọng lực P thành hai thành phần: thành phần song song với mặt nghiêng P·sinα gây gia tốc cho vật. Gia tốc a = g·sinα = 10 × sin30° = 10 × 0,5 = 5 m/s² (không phụ thuộc khối lượng khi bỏ qua ma sát).","t":"ly-lop10","g":10,"l":"thu-thach"},{"p":"Một người tác dụng một lực 30 N vuông góc với cánh cửa tại điểm cách bản lề (trục quay) 0,4 m. Moment của lực này đối với trục quay của cánh cửa là:","o":["7,5 N·m","12 N·m","75 N·m","120 N·m"],"a":"12 N·m","h":"Moment của lực: M = F·d, với d là cánh tay đòn.","e":"M = F·d = 30 × 0,4 = 12 N·m. Cánh tay đòn càng lớn thì cùng một lực tạo ra moment càng lớn.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Một đòn bẩy có trục quay cố định. Ở một phía, một vật có trọng lượng 60 N treo cách trục quay 0,2 m. Muốn đòn bẩy cân bằng nằm ngang, cần tác dụng vào phía bên kia một lực vuông góc với đòn bẩy tại điểm cách trục quay 0,6 m. Độ lớn của lực này là:","o":["20 N","30 N","120 N","180 N"],"a":"20 N","h":"Khi cân bằng theo quy tắc moment: F₁·d₁ = F₂·d₂.","e":"Áp dụng quy tắc moment: F × 0,6 = 60 × 0,2 = 12 → F = 12 / 0,6 = 20 N.","t":"ly-lop10","g":10,"l":"thu-thach"},{"p":"Điều kiện để một vật rắn cân bằng (đứng yên) dưới tác dụng của nhiều lực là:","o":["Tổng các lực tác dụng lên vật bằng 0, còn tổng moment của các lực thì tùy ý","Tổng moment của các lực đối với một trục quay bất kì bằng 0, còn tổng các lực thì tùy ý","Tổng các lực tác dụng lên vật bằng 0 và tổng moment của các lực đối với một trục quay bất kì cũng bằng 0","Chỉ cần vật có một điểm tựa cố định là vật luôn cân bằng"],"a":"Tổng các lực tác dụng lên vật bằng 0 và tổng moment của các lực đối với một trục quay bất kì cũng bằng 0","h":"Vật không chuyển động tịnh tiến và cũng không quay thì mới cân bằng hoàn toàn.","e":"Vật rắn cân bằng khi hợp lực tác dụng bằng 0 (không chuyển động tịnh tiến) và tổng moment của các lực đối với bất kì trục quay nào cũng bằng 0 (không quay).","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Một chiếc đu quay quay đều và thực hiện được 15 vòng trong 30 s. Chu kì quay của đu quay là:","o":["0,5 s","1 s","450 s","2 s"],"a":"2 s","h":"Chu kì là thời gian vật thực hiện một vòng: T = t/N.","e":"T = t/N = 30 / 15 = 2 s. Tức là cứ mỗi 2 giây đu quay hoàn thành một vòng.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Một động cơ quay đều 300 vòng trong một phút. Tần số quay của động cơ là:","o":["300 Hz","5 Hz","0,2 Hz","50 Hz"],"a":"5 Hz","h":"Tần số là số vòng quay trong một giây; đổi 1 phút = 60 s.","e":"f = 300 vòng / 60 s = 5 vòng/s = 5 Hz.","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Một quả bóng được ném xiên lên với vận tốc ban đầu 20 m/s theo phương hợp với phương ngang một góc 30°. Bỏ qua sức cản không khí. Thành phần của vận tốc ban đầu theo phương thẳng đứng có độ lớn là:","o":["20 m/s","17,3 m/s","10 m/s","5 m/s"],"a":"10 m/s","h":"Phân tích vận tốc ban đầu: thành phần đứng v₀y = v₀·sin α.","e":"v₀y = v₀·sin30° = 20 × 0,5 = 10 m/s. (Thành phần ngang là v₀x = v₀·cos30° ≈ 17,3 m/s và không đổi trong suốt quá trình chuyển động.)","t":"ly-lop10","g":10,"l":"thu-thach"},{"p":"Hai lực cùng phương, ngược chiều tác dụng lên một vật, có độ lớn lần lượt là 12 N và 7 N. Hợp lực của hai lực này có đặc điểm là:","o":["Độ lớn 19 N, cùng hướng với lực 12 N","Độ lớn 5 N, cùng hướng với lực 12 N","Độ lớn 5 N, cùng hướng với lực 7 N","Độ lớn 19 N, cùng hướng với lực 7 N"],"a":"Độ lớn 5 N, cùng hướng với lực 12 N","h":"Hai lực ngược chiều: độ lớn hợp lực bằng hiệu hai độ lớn.","e":"Hợp lực của hai lực cùng phương, ngược chiều có độ lớn F = 12 − 7 = 5 N và cùng hướng với lực lớn hơn (lực 12 N).","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Một vật có khối lượng 4 kg đặt trên mặt phẳng nghiêng góc 30° so với phương ngang. Lấy g = 10 m/s². Khi phân tích trọng lực tác dụng lên vật thành hai thành phần (song song và vuông góc với mặt nghiêng), thành phần song song với mặt nghiêng có độ lớn là:","o":["40 N","34,6 N","20 N","10 N"],"a":"20 N","h":"Trọng lượng P = mg; thành phần song song với mặt nghiêng là P·sin α.","e":"P = mg = 4 × 10 = 40 N. Thành phần song song: P·sin30° = 40 × 0,5 = 20 N — đây là thành phần kéo vật trượt xuống dọc mặt nghiêng (thành phần vuông góc là P·cos30° ≈ 34,6 N).","t":"ly-lop10","g":10,"l":"nhe-nhang"},{"p":"Một vật dao động điều hoà có chu kì T = 0,5 s. Tần số của dao động là","o":["0,5 Hz","1 Hz","2 Hz","4 Hz"],"a":"2 Hz","h":"Tần số f = 1/T.","e":"f = 1/T = 1/0,5 = 2 Hz.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Biên độ của dao động điều hoà là","o":["quãng đường vật đi được trong một chu kì","độ lệch lớn nhất của vật so với vị trí cân bằng","số dao động vật thực hiện trong một giây","thời gian vật thực hiện một dao động toàn phần"],"a":"độ lệch lớn nhất của vật so với vị trí cân bằng","h":"Biên độ kí hiệu là A, đo từ vị trí cân bằng.","e":"Biên độ A là độ lệch (li độ) lớn nhất của vật so với vị trí cân bằng trong quá trình dao động.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Một con lắc lò xo có độ cứng k không đổi. Nếu tăng khối lượng của vật lên 4 lần thì chu kì dao động của con lắc","o":["tăng 2 lần","tăng 4 lần","giảm 2 lần","không thay đổi"],"a":"tăng 2 lần","h":"Chu kì con lắc lò xo tỉ lệ với căn bậc hai của khối lượng.","e":"T = 2π√(m/k). Khi m tăng 4 lần thì T tăng √4 = 2 lần.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Chu kì dao động nhỏ của con lắc đơn KHÔNG phụ thuộc vào","o":["chiều dài dây treo","gia tốc trọng trường nơi đặt con lắc","khối lượng của vật nặng","vị trí địa lí nơi làm thí nghiệm"],"a":"khối lượng của vật nặng","h":"Nhớ công thức chu kì con lắc đơn T = 2π√(l/g).","e":"T = 2π√(l/g) chỉ phụ thuộc chiều dài l và gia tốc trọng trường g (g thay đổi theo vị trí địa lí), không phụ thuộc khối lượng vật nặng.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Một con lắc đơn có chiều dài dây treo 1 m dao động nhỏ tại nơi có g = 10 m/s². Lấy π² = 10. Chu kì dao động của con lắc xấp xỉ bằng","o":["1 s","2 s","0,5 s","4 s"],"a":"2 s","h":"Áp dụng T = 2π√(l/g) rồi thay số.","e":"T = 2π√(l/g) = 2π√(1/10) = 2π/√10 ≈ 2 s (vì π² = 10 nên π = √10).","t":"ly-lop11","g":11,"l":"thu-thach"},{"p":"Trong dao động điều hoà, khi vật ở vị trí biên thì đại lượng nào sau đây bằng 0?","o":["Li độ","Gia tốc","Vận tốc","Lực kéo về"],"a":"Vận tốc","h":"Ở vị trí biên vật đổi chiều chuyển động.","e":"Tại vị trí biên, vật dừng lại để đổi chiều chuyển động nên vận tốc bằng 0; li độ, gia tốc và lực kéo về đều đạt độ lớn cực đại.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Cơ năng của một con lắc lò xo dao động điều hoà (bỏ qua ma sát) tỉ lệ với","o":["biên độ dao động","bình phương biên độ dao động","căn bậc hai của biên độ dao động","nghịch đảo của biên độ dao động"],"a":"bình phương biên độ dao động","h":"Cơ năng W = ½kA².","e":"Cơ năng của con lắc lò xo W = ½kA², tỉ lệ với bình phương biên độ A và được bảo toàn khi bỏ qua ma sát.","t":"ly-lop11","g":11,"l":"thu-thach"},{"p":"Dao động tắt dần là dao động có","o":["biên độ tăng dần theo thời gian","tần số tăng dần theo thời gian","biên độ giảm dần theo thời gian do ma sát và lực cản","chu kì giảm dần theo thời gian"],"a":"biên độ giảm dần theo thời gian do ma sát và lực cản","h":"Hãy nghĩ tới chiếc xích đu khi không được đẩy thêm.","e":"Do ma sát và lực cản của môi trường, cơ năng giảm dần nên biên độ của dao động tắt dần giảm dần theo thời gian.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Hiện tượng cộng hưởng xảy ra khi tần số của lực cưỡng bức bằng tần số riêng của hệ. Trường hợp nào sau đây là cộng hưởng GÂY HẠI?","o":["Hộp đàn ghi-ta làm tiếng đàn vang to hơn","Cầu rung mạnh, có thể sập khi đoàn người bước đều qua cầu","Đẩy xích đu đúng nhịp để xích đu lên cao","Âm thoa rung mạnh khi đặt gần một âm thoa khác đang rung cùng tần số"],"a":"Cầu rung mạnh, có thể sập khi đoàn người bước đều qua cầu","h":"Cộng hưởng làm biên độ dao động tăng mạnh; hãy tìm trường hợp biên độ lớn gây nguy hiểm.","e":"Khi đoàn người bước đều qua cầu với tần số bước chân trùng tần số riêng của cầu, cộng hưởng làm cầu rung với biên độ rất lớn, có thể gây sập cầu. Các trường hợp còn lại là ứng dụng có lợi của cộng hưởng.","t":"ly-lop11","g":11,"l":"thu-thach"},{"p":"Một vật dao động điều hoà thực hiện được 20 dao động toàn phần trong 10 s. Tần số dao động của vật là","o":["0,5 Hz","20 Hz","200 Hz","2 Hz"],"a":"2 Hz","h":"Tần số là số dao động toàn phần trong 1 giây.","e":"f = 20/10 = 2 Hz.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Sóng cơ là","o":["dao động cơ lan truyền trong một môi trường","sự chuyển dời vật chất theo phương truyền sóng","dòng chảy của các phần tử môi trường theo sóng","sự truyền đi của vật chất từ nguồn ra xung quanh"],"a":"dao động cơ lan truyền trong một môi trường","h":"Khi sóng truyền đi, các phần tử môi trường chỉ dao động tại chỗ.","e":"Sóng cơ là dao động cơ lan truyền trong một môi trường vật chất; các phần tử môi trường chỉ dao động quanh vị trí cân bằng, không chuyển dời theo sóng.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Một sóng cơ có tần số 170 Hz truyền trong không khí với tốc độ 340 m/s. Bước sóng của sóng này là","o":["1 m","2 m","0,5 m","4 m"],"a":"2 m","h":"Dùng công thức λ = v/f.","e":"λ = v/f = 340/170 = 2 m.","t":"ly-lop11","g":11,"l":"thu-thach"},{"p":"Sóng dọc là sóng mà phương dao động của các phần tử môi trường","o":["trùng với phương truyền sóng","vuông góc với phương truyền sóng","luôn hướng thẳng đứng","luôn hướng về nguồn sóng"],"a":"trùng với phương truyền sóng","h":"Sóng âm trong không khí là một ví dụ của sóng dọc.","e":"Ở sóng dọc, các phần tử môi trường dao động dọc theo phương truyền sóng (ví dụ sóng âm). Ở sóng ngang, phương dao động vuông góc với phương truyền sóng.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Siêu âm là sóng âm có tần số","o":["nhỏ hơn 16 Hz","từ 16 Hz đến 20.000 Hz","lớn hơn 20.000 Hz","bằng đúng 20.000 Hz"],"a":"lớn hơn 20.000 Hz","h":"Tai người chỉ nghe được âm trong khoảng 16 Hz đến 20.000 Hz.","e":"Âm có tần số lớn hơn 20.000 Hz gọi là siêu âm, tai người không nghe được; dơi và một số động vật sử dụng siêu âm để định hướng.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Hạ âm là sóng âm có tần số","o":["nhỏ hơn 16 Hz","từ 16 Hz đến 20.000 Hz","lớn hơn 20.000 Hz","lớn hơn 16 Hz"],"a":"nhỏ hơn 16 Hz","h":"Hạ âm nằm ở phía dưới ngưỡng nghe của tai người.","e":"Âm có tần số nhỏ hơn 16 Hz gọi là hạ âm, tai người không nghe được; sóng địa chấn và tiếng của voi là ví dụ về hạ âm.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Sóng âm KHÔNG truyền được trong môi trường nào sau đây?","o":["Chất rắn","Chất lỏng","Chất khí","Chân không"],"a":"Chân không","h":"Sóng cơ cần môi trường vật chất để truyền.","e":"Sóng âm là sóng cơ nên cần môi trường vật chất (rắn, lỏng, khí) để truyền; trong chân không không có phần tử vật chất nên âm không truyền được.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Trong hiện tượng giao thoa của hai sóng cùng tần số, tại vị trí cực đại giao thoa, hai sóng thành phần luôn","o":["ngược pha nhau và triệt tiêu nhau","cùng pha nhau và tăng cường lẫn nhau","lệch pha nhau một lượng bất kì","có biên độ bằng 0"],"a":"cùng pha nhau và tăng cường lẫn nhau","h":"Cực đại giao thoa là nơi dao động mạnh nhất.","e":"Tại cực đại giao thoa, hai sóng thành phần đến cùng pha nên tăng cường lẫn nhau, tạo dao động tổng hợp có biên độ lớn nhất.","t":"ly-lop11","g":11,"l":"thu-thach"},{"p":"Trong sóng dừng trên dây, nút sóng là điểm","o":["dao động với biên độ lớn nhất","luôn đứng yên","dao động cùng pha với nguồn sóng","truyền đi dọc theo dây"],"a":"luôn đứng yên","h":"Sóng dừng tạo ra các điểm nút và điểm bụng cố định trên dây.","e":"Trong sóng dừng, nút sóng là điểm luôn đứng yên (biên độ bằng 0), còn bụng sóng là điểm dao động với biên độ lớn nhất.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Ứng dụng của siêu âm trong y tế là","o":["chụp X-quang lồng ngực","chụp cộng hưởng từ (MRI)","đo điện tâm đồ","siêu âm chẩn đoán hình ảnh, ví dụ theo dõi thai nhi"],"a":"siêu âm chẩn đoán hình ảnh, ví dụ theo dõi thai nhi","h":"Ứng dụng này dùng sóng âm tần số cao phản xạ từ các cơ quan trong cơ thể.","e":"Máy siêu âm y tế phát siêu âm vào cơ thể và thu sóng phản xạ để dựng hình ảnh các cơ quan, ví dụ theo dõi thai nhi, mà không dùng tia phóng xạ.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Một sóng cơ có bước sóng 0,5 m và tần số 10 Hz. Tốc độ truyền sóng là","o":["0,05 m/s","5 m/s","15 m/s","50 m/s"],"a":"5 m/s","h":"Tốc độ truyền sóng v = λf.","e":"v = λf = 0,5 × 10 = 5 m/s.","t":"ly-lop11","g":11,"l":"thu-thach"},{"p":"Theo định luật Cu-lông, nếu tăng khoảng cách giữa hai điện tích điểm lên gấp đôi (độ lớn các điện tích không đổi) thì lực tương tác giữa chúng","o":["giảm 4 lần","giảm 2 lần","tăng 2 lần","không thay đổi"],"a":"giảm 4 lần","h":"Lực Cu-lông tỉ lệ nghịch với bình phương khoảng cách.","e":"F = k|q₁q₂|/r². Khi r tăng 2 lần thì r² tăng 4 lần nên lực giảm 4 lần.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Hai điện tích điểm q₁ = q₂ = 10⁻⁶ C đặt cách nhau 30 cm trong chân không. Lấy k = 9.10⁹ N.m²/C². Lực tương tác giữa hai điện tích là","o":["0,01 N","1 N","10 N","0,1 N"],"a":"0,1 N","h":"Đổi 30 cm = 0,3 m rồi áp dụng F = k|q₁q₂|/r².","e":"F = 9.10⁹ × (10⁻⁶)²/(0,3)² = 9.10⁹ × 10⁻¹²/0,09 = 0,1 N.","t":"ly-lop11","g":11,"l":"thu-thach"},{"p":"Cường độ điện trường tại một điểm đặc trưng cho điện trường về phương diện","o":["tác dụng lực lên điện tích đặt tại điểm đó","khả năng tích trữ điện tích của điện trường","hướng truyền đi của điện trường","độ lớn của điện tích nguồn"],"a":"tác dụng lực lên điện tích đặt tại điểm đó","h":"Cường độ điện trường E = F/q.","e":"Cường độ điện trường tại một điểm đặc trưng cho tác dụng lực của điện trường lên điện tích đặt tại điểm đó, được xác định bằng E = F/q.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Đường sức điện của một điện tích điểm dương đứng yên có hướng","o":["ra xa điện tích","vào điện tích","theo vòng tròn quanh điện tích","luôn hướng xuống dưới"],"a":"ra xa điện tích","h":"Chiều đường sức là chiều của vectơ cường độ điện trường.","e":"Đường sức điện của điện tích dương hướng ra xa điện tích (vào điện tích đối với điện tích âm), và các đường sức không bao giờ cắt nhau.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Khi di chuyển một điện tích q = 2 C giữa hai điểm có hiệu điện thế U = 10 V, công của lực điện thực hiện là","o":["5 J","0,2 J","20 J","12 J"],"a":"20 J","h":"Công của lực điện A = qU.","e":"A = qU = 2 × 10 = 20 J.","t":"ly-lop11","g":11,"l":"thu-thach"},{"p":"Tụ điện là hệ hai vật dẫn đặt gần nhau, ngăn cách bởi một lớp điện môi, dùng để","o":["tích trữ điện tích và năng lượng điện","tạo ra dòng điện liên tục trong mạch","biến đổi điện áp của dòng điện xoay chiều","đo cường độ dòng điện"],"a":"tích trữ điện tích và năng lượng điện","h":"Tụ điện có mặt trong hầu hết các mạch điện tử.","e":"Tụ điện dùng để tích trữ điện tích và năng lượng điện trường giữa hai bản; nó được dùng rộng rãi trong các mạch điện tử, mạch lọc và mạch dao động.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Điện dung của một tụ điện KHÔNG phụ thuộc vào","o":["diện tích phần đối diện của hai bản tụ","khoảng cách giữa hai bản tụ","bản chất lớp điện môi giữa hai bản tụ","hiệu điện thế đặt vào hai bản tụ"],"a":"hiệu điện thế đặt vào hai bản tụ","h":"Điện dung chỉ phụ thuộc cấu tạo của tụ điện.","e":"Điện dung C = Q/U là hằng số đặc trưng cho cấu tạo của tụ (diện tích bản, khoảng cách, điện môi); khi U thay đổi thì Q thay đổi theo nhưng C không đổi.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Một điện trở R = 4 Ω được mắc vào nguồn có hiệu điện thế U = 12 V. Cường độ dòng điện chạy qua điện trở là","o":["48 A","0,33 A","16 A","3 A"],"a":"3 A","h":"Áp dụng định luật Ôm I = U/R.","e":"I = U/R = 12/4 = 3 A.","t":"ly-lop11","g":11,"l":"thu-thach"},{"p":"Điện trở của một dây dẫn kim loại sẽ tăng lên khi","o":["giảm chiều dài của dây","tăng tiết diện của dây","tăng chiều dài của dây","đổi sang vật liệu dẫn điện tốt hơn"],"a":"tăng chiều dài của dây","h":"Điện trở R = ρl/S.","e":"Điện trở của dây dẫn tỉ lệ thuận với chiều dài l, tỉ lệ nghịch với tiết diện S và phụ thuộc điện trở suất ρ của vật liệu; tăng chiều dài dây thì điện trở tăng.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Hai điện trở R₁ = 2 Ω và R₂ = 4 Ω mắc nối tiếp. Điện trở tương đương của đoạn mạch là","o":["1,33 Ω","8 Ω","3 Ω","6 Ω"],"a":"6 Ω","h":"Mạch nối tiếp: R = R₁ + R₂.","e":"Điện trở tương đương của mạch nối tiếp: R = R₁ + R₂ = 2 + 4 = 6 Ω.","t":"ly-lop11","g":11,"l":"thu-thach"},{"p":"Hai điện trở R₁ = R₂ = 6 Ω mắc song song. Điện trở tương đương của đoạn mạch là","o":["12 Ω","6 Ω","3 Ω","36 Ω"],"a":"3 Ω","h":"Mạch song song: 1/R = 1/R₁ + 1/R₂.","e":"1/R = 1/6 + 1/6 = 1/3 nên R = 3 Ω. Khi hai điện trở bằng nhau mắc song song, điện trở tương đương bằng một nửa mỗi điện trở.","t":"ly-lop11","g":11,"l":"thu-thach"},{"p":"Một bóng đèn hoạt động với hiệu điện thế 220 V và cường độ dòng điện 0,5 A. Công suất điện của bóng đèn là","o":["110 W","440 W","220 W","44 W"],"a":"110 W","h":"Công suất điện P = U.I.","e":"P = U.I = 220 × 0,5 = 110 W.","t":"ly-lop11","g":11,"l":"thu-thach"},{"p":"Dòng điện I = 2 A chạy qua một điện trở R = 5 Ω trong thời gian 10 s. Nhiệt lượng toả ra trên điện trở theo định luật Jun – Lenxơ là","o":["100 J","200 J","400 J","1.000 J"],"a":"200 J","h":"Nhiệt lượng Q = I²Rt.","e":"Q = I²Rt = 2² × 5 × 10 = 200 J.","t":"ly-lop11","g":11,"l":"thu-thach"},{"p":"Suất điện động của một nguồn điện là đại lượng đặc trưng cho","o":["độ mạnh của dòng điện trong mạch ngoài","điện trở trong của nguồn điện","khả năng thực hiện công của nguồn điện khi di chuyển điện tích bên trong nguồn","nhiệt lượng toả ra trên mạch ngoài"],"a":"khả năng thực hiện công của nguồn điện khi di chuyển điện tích bên trong nguồn","h":"Suất điện động gắn với công của lực lạ bên trong nguồn.","e":"Suất điện động đặc trưng cho khả năng thực hiện công của nguồn điện: nó bằng công của lực lạ khi di chuyển một đơn vị điện tích dương bên trong nguồn.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Việc làm nào sau đây KHÔNG an toàn khi sử dụng điện?","o":["Ngắt cầu dao trước khi sửa chữa thiết bị điện","Dùng bút thử điện để kiểm tra trước khi chạm vào dây dẫn","Không chạm vào dây điện bị hở, tróc vỏ cách điện","Dùng tay ướt để cắm phích điện vào ổ cắm"],"a":"Dùng tay ướt để cắm phích điện vào ổ cắm","h":"Nước làm da giảm điện trở, dễ gây điện giật nguy hiểm.","e":"Tay ướt làm điện trở của cơ thể giảm mạnh, dòng điện qua người tăng lên dễ gây giật điện nguy hiểm; vì vậy không được dùng tay ướt thao tác với thiết bị điện.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Một vật dao động điều hoà theo phương trình x = 5cos(4πt) (x tính bằng cm, t tính bằng s). Biên độ dao động và chu kì dao động của vật lần lượt là:","o":["5 cm và 2 s","5 cm và 0,5 s","10 cm và 0,5 s","4 cm và 0,5 s"],"a":"5 cm và 0,5 s","h":"So sánh với phương trình tổng quát x = Acos(ωt + φ): A là hệ số đứng trước hàm cos, còn T = 2π / ω.","e":"Từ phương trình: biên độ A = 5 cm, tần số góc ω = 4π rad/s. Chu kì T = 2π / ω = 2π / (4π) = 0,5 s.","t":"ly-lop11","g":11,"l":"thu-thach"},{"p":"Một vật dao động điều hoà với biên độ A = 4 cm và tần số góc ω = 10 rad/s. Tốc độ cực đại của vật trong quá trình dao động là:","o":["4 cm/s","400 cm/s","2,5 cm/s","40 cm/s"],"a":"40 cm/s","h":"Tốc độ cực đại v_max = A·ω, đạt được khi vật đi qua vị trí cân bằng.","e":"Tốc độ cực đại v_max = Aω = 4 × 10 = 40 cm/s.","t":"ly-lop11","g":11,"l":"thu-thach"},{"p":"Phát biểu nào sau đây là ĐÚNG về sóng điện từ?","o":["Sóng điện từ chỉ truyền được trong các môi trường vật chất như không khí, nước","Sóng điện từ là sóng dọc, giống như sóng âm","Sóng điện từ truyền trong chân không với tốc độ bằng tốc độ âm thanh","Sóng điện từ là sự lan truyền của điện từ trường trong không gian, truyền được cả trong chân không với tốc độ xấp xỉ 3.10⁸ m/s"],"a":"Sóng điện từ là sự lan truyền của điện từ trường trong không gian, truyền được cả trong chân không với tốc độ xấp xỉ 3.10⁸ m/s","h":"Hãy nghĩ tới ánh sáng Mặt Trời: nó đến được Trái Đất dù giữa Mặt Trời và Trái Đất là khoảng chân không.","e":"Sóng điện từ là điện từ trường lan truyền trong không gian. Nó không cần môi trường vật chất nên truyền được cả trong chân không với tốc độ c ≈ 3.10⁸ m/s, và là sóng ngang.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Trong hiện tượng giao thoa của hai sóng có cùng tần số và cùng biên độ, một điểm dao động với biên độ cực tiểu khi hiệu đường đi của hai sóng từ hai nguồn tới điểm đó bằng:","o":["một số nguyên lần bước sóng: d₂ − d₁ = kλ","một số lẻ lần một phần tư bước sóng: d₂ − d₁ = (2k + 1)λ/4","một số lẻ lần nửa bước sóng: d₂ − d₁ = (2k + 1)λ/2","0"],"a":"một số lẻ lần nửa bước sóng: d₂ − d₁ = (2k + 1)λ/2","h":"Cực tiểu giao thoa xảy ra khi hai sóng tới điểm đó ngược pha nhau và triệt tiêu nhau.","e":"Hai sóng tới một điểm sẽ ngược pha khi hiệu đường đi bằng một số lẻ lần nửa bước sóng: d₂ − d₁ = (2k + 1)λ/2 với k = 0, ±1, ±2, ... Khi đó hai sóng triệt tiêu nhau nên điểm dao động với biên độ cực tiểu.","t":"ly-lop11","g":11,"l":"thu-thach"},{"p":"Hai bản phẳng song song tích điện trái dấu tạo ra điện trường đều ở giữa hai bản. Hiệu điện thế giữa hai bản là 100 V, khoảng cách giữa hai bản là 2 cm. Cường độ điện trường giữa hai bản có độ lớn là:","o":["200 V/m","5 000 V/m","50 V/m","2 V/m"],"a":"5 000 V/m","h":"Trong điện trường đều: E = U / d, chú ý đổi khoảng cách sang mét.","e":"Đổi d = 2 cm = 0,02 m. Cường độ điện trường E = U / d = 100 / 0,02 = 5 000 V/m.","t":"ly-lop11","g":11,"l":"thu-thach"},{"p":"Điện thế tại một điểm trong điện trường là đại lượng đặc trưng cho điện trường về:","o":["độ lớn của lực điện tác dụng lên điện tích đặt tại điểm đó","năng lượng của điện tích đặt tại điểm đó","khả năng sinh công khi dịch chuyển một đơn vị điện tích từ điểm đó đến mốc điện thế","tốc độ dịch chuyển của điện tích tại điểm đó"],"a":"khả năng sinh công khi dịch chuyển một đơn vị điện tích từ điểm đó đến mốc điện thế","h":"Điện thế được định nghĩa qua tỉ số V = A / q, trong đó A là công của lực điện.","e":"Điện thế tại một điểm V = A/q, trong đó A là công của lực điện khi dịch chuyển điện tích q từ điểm đó đến mốc điện thế (thường chọn là vô cực). Vì vậy điện thế đặc trưng cho khả năng sinh công của điện trường tại điểm đó đối với một đơn vị điện tích.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Một tụ điện được tích điện với điện tích Q = 20 µC khi đặt vào hai bản tụ hiệu điện thế U = 10 V. Điện dung của tụ điện là:","o":["0,5 µF","200 µF","20 µF","2 µF"],"a":"2 µF","h":"Điện dung của tụ điện C = Q / U.","e":"Điện dung C = Q / U = 20 / 10 = 2 µF.","t":"ly-lop11","g":11,"l":"thu-thach"},{"p":"Trong thời gian 10 s, có một điện lượng 30 C chuyển qua tiết diện thẳng của một dây dẫn. Cường độ dòng điện chạy qua dây dẫn là:","o":["3 A","300 A","0,33 A","30 A"],"a":"3 A","h":"Cường độ dòng điện I = q / t.","e":"Cường độ dòng điện I = q / t = 30 / 10 = 3 A.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Điện trở của một dây dẫn kim loại đồng chất, có tiết diện đều phụ thuộc vào chiều dài l và tiết diện S của dây như thế nào?","o":["Tỉ lệ nghịch với chiều dài l và tỉ lệ thuận với tiết diện S","Tỉ lệ thuận với chiều dài l và tỉ lệ nghịch với tiết diện S","Chỉ phụ thuộc vào chiều dài l, không phụ thuộc vào tiết diện S","Không phụ thuộc vào cả chiều dài và tiết diện của dây"],"a":"Tỉ lệ thuận với chiều dài l và tỉ lệ nghịch với tiết diện S","h":"Nhớ công thức điện trở của dây dẫn: R = ρl / S.","e":"Theo công thức R = ρl/S, điện trở tỉ lệ thuận với chiều dài l và tỉ lệ nghịch với tiết diện S: dây càng dài điện trở càng lớn, dây có tiết diện càng lớn điện trở càng nhỏ.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Một vật dao động điều hoà với biên độ A = 5 cm và tần số góc ω = 4 rad/s. Độ lớn gia tốc cực đại của vật là bao nhiêu?","o":["20 cm/s²","80 cm/s²","40 cm/s²","100 cm/s²"],"a":"80 cm/s²","h":"Gia tốc cực đại trong dao động điều hoà: a_max = ω²A.","e":"Gia tốc trong dao động điều hoà: a = −ω²x, đạt độ lớn cực đại tại vị trí biên: a_max = ω²A = 4² × 5 = 16 × 5 = 80 cm/s².","t":"ly-lop11","g":11,"l":"thu-thach"},{"p":"Một con lắc lò xo dao động điều hoà (bỏ qua ma sát). Khi vật đi qua vị trí cân bằng, năng lượng của con lắc có đặc điểm gì?","o":["Động năng và thế năng đều bằng không","Động năng đạt giá trị cực đại, thế năng đạt giá trị cực tiểu","Thế năng đạt giá trị cực đại, động năng bằng không","Động năng bằng thế năng"],"a":"Động năng đạt giá trị cực đại, thế năng đạt giá trị cực tiểu","h":"Tại vị trí cân bằng, vật chuyển động nhanh nhất.","e":"Trong dao động điều hoà, năng lượng liên tục chuyển hoá qua lại giữa động năng và thế năng nhưng tổng cơ năng không đổi (khi bỏ qua ma sát). Tại vị trí cân bằng, vật có tốc độ lớn nhất nên động năng cực đại, còn thế năng cực tiểu; tại vị trí biên thì ngược lại.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Thế năng của một điện tích điểm q đặt tại một điểm trong điện trường được xác định như thế nào?","o":["Chỉ phụ thuộc vào cường độ điện trường, không phụ thuộc điện tích","Bằng tích của điện tích đó với điện thế tại điểm đặt điện tích: W = qV","Luôn bằng không vì điện trường không có thế năng","Bằng thương số giữa điện thế và điện tích"],"a":"Bằng tích của điện tích đó với điện thế tại điểm đặt điện tích: W = qV","h":"Thế năng điện và điện thế liên hệ với nhau qua chính điện tích q.","e":"Thế năng của điện tích q tại một điểm trong điện trường là W = qV, với V là điện thế tại điểm đó. Khi điện tích di chuyển giữa hai điểm, công của lực điện bằng độ giảm thế năng của điện tích: A = q(V₁ − V₂) = qU.","t":"ly-lop11","g":11,"l":"thu-thach"},{"p":"Hai nguồn điện giống nhau, mỗi nguồn có suất điện động 3 V và điện trở trong 0,5 Ω, được ghép nối tiếp thành một bộ nguồn. Suất điện động và điện trở trong của bộ nguồn là","o":["3 V và 0,5 Ω","6 V và 1 Ω","6 V và 0,25 Ω","3 V và 1 Ω"],"a":"6 V và 1 Ω","h":"Ghép nối tiếp n nguồn giống nhau: Eb = nE, rb = nr.","e":"Khi ghép nối tiếp, các nguồn nối đuôi nhau nên suất điện động cộng lại: Eb = 2 × 3 = 6 V; điện trở trong cũng mắc nối tiếp: rb = 2 × 0,5 = 1 Ω.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Bốn nguồn điện giống nhau, mỗi nguồn có suất điện động 6 V và điện trở trong 1 Ω, được ghép song song thành một bộ nguồn. Suất điện động và điện trở trong của bộ nguồn là","o":["24 V và 4 Ω","6 V và 4 Ω","24 V và 0,25 Ω","6 V và 0,25 Ω"],"a":"6 V và 0,25 Ω","h":"Ghép song song các nguồn giống nhau: Eb = E, rb = r/n.","e":"Khi ghép song song các nguồn giống nhau, suất điện động của bộ bằng suất điện động của một nguồn: Eb = 6 V; điện trở trong giảm n lần: rb = 1/4 = 0,25 Ω.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Một bộ nguồn gồm 3 pin giống nhau ghép nối tiếp, mỗi pin có suất điện động 1,5 V và điện trở trong 0,5 Ω. Mắc bộ nguồn với một điện trở ngoài R = 3 Ω thành mạch kín. Cường độ dòng điện chạy trong mạch là","o":["1,5 A","1 A","0,75 A","3 A"],"a":"1 A","h":"Tìm Eb, rb của bộ nguồn nối tiếp rồi dùng định luật Ôm cho toàn mạch: I = Eb/(R + rb).","e":"Bộ nguồn nối tiếp: Eb = 3 × 1,5 = 4,5 V, rb = 3 × 0,5 = 1,5 Ω. Định luật Ôm cho toàn mạch: I = 4,5/(3 + 1,5) = 1 A.","t":"ly-lop11","g":11,"l":"thu-thach"},{"p":"Một nguồn điện có suất điện động 12 V và điện trở trong 1 Ω được mắc với điện trở ngoài 5 Ω thành mạch kín. Hiệu điện thế giữa hai cực của nguồn điện là","o":["12 V","2 V","10 V","11 V"],"a":"10 V","h":"Hiệu điện thế mạch ngoài U = E − Ir, với I là cường độ dòng điện trong mạch.","e":"Cường độ dòng điện: I = E/(R + r) = 12/(5 + 1) = 2 A. Hiệu điện thế hai cực: U = E − Ir = 12 − 2 × 1 = 10 V (nhỏ hơn suất điện động do độ giảm điện thế trong nguồn).","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Hiện tượng đoản mạch xảy ra khi nối trực tiếp hai cực của một nguồn điện bằng dây dẫn có điện trở không đáng kể. Phát biểu nào sau đây đúng về hiện tượng này?","o":["Cường độ dòng điện trong mạch rất lớn vì điện trở toàn mạch chỉ còn điện trở trong rất nhỏ của nguồn, có thể làm hỏng nguồn và gây cháy nổ","Cường độ dòng điện bằng không vì dây dẫn nối tắt không tiêu thụ điện năng","Cường độ dòng điện rất nhỏ vì hiệu điện thế giữa hai cực của nguồn giảm xuống bằng không","Cường độ dòng điện không thay đổi so với khi mắc tải vì điện trở trong không ảnh hưởng đến dòng điện"],"a":"Cường độ dòng điện trong mạch rất lớn vì điện trở toàn mạch chỉ còn điện trở trong rất nhỏ của nguồn, có thể làm hỏng nguồn và gây cháy nổ","h":"Khi đoản mạch, điện trở mạch ngoài R ≈ 0, hãy xét công thức I = E/(R + r).","e":"Khi đoản mạch, R ≈ 0 nên I = E/r. Vì điện trở trong r của nguồn thường rất nhỏ nên dòng điện rất lớn, sinh nhiệt mạnh, dễ làm hỏng nguồn, cháy dây và gây hỏa hoạn.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Một sợi dây đàn hồi dài 1 m, hai đầu cố định. Trên dây xuất hiện sóng dừng với 4 bó sóng. Bước sóng của sóng trên dây là","o":["0,25 m","2 m","0,5 m","1 m"],"a":"0,5 m","h":"Dây hai đầu cố định có sóng dừng khi chiều dài dây bằng số nguyên lần nửa bước sóng: L = kλ/2.","e":"Điều kiện sóng dừng trên dây hai đầu cố định: L = kλ/2 với k là số bó sóng. Thay số: 1 = 4λ/2 = 2λ, suy ra λ = 0,5 m.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Trên một sợi dây có sóng dừng với bước sóng 40 cm. Khoảng cách giữa hai nút sóng liên tiếp trên dây bằng","o":["40 cm","20 cm","10 cm","80 cm"],"a":"20 cm","h":"Trong sóng dừng, hai nút liên tiếp (hoặc hai bụng liên tiếp) cách nhau nửa bước sóng.","e":"Khoảng cách giữa hai nút sóng liên tiếp bằng λ/2 = 40/2 = 20 cm.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Trong hiện tượng giao thoa sóng trên mặt nước với hai nguồn kết hợp cùng pha, bước sóng là 4 cm. Một điểm M trên mặt nước cách hai nguồn lần lượt là 24 cm và 16 cm. Tại điểm M có","o":["cực tiểu giao thoa bậc 2","cực đại giao thoa bậc 8","cực tiểu giao thoa bậc 1","cực đại giao thoa bậc 2"],"a":"cực đại giao thoa bậc 2","h":"Tính hiệu đường đi d1 − d2 rồi so sánh với bước sóng: cực đại khi hiệu bằng số nguyên lần λ.","e":"Hiệu đường đi: d1 − d2 = 24 − 16 = 8 cm = 2λ. Hiệu bằng số nguyên lần bước sóng nên tại M hai sóng tăng cường nhau, M là cực đại giao thoa bậc 2.","t":"ly-lop11","g":11,"l":"thu-thach"},{"p":"Trong thí nghiệm giao thoa sóng trên mặt nước, hai nguồn kết hợp cùng pha S1 và S2 cách nhau 12 cm, bước sóng là 3 cm. Số điểm dao động với biên độ cực đại trên đoạn thẳng nối hai nguồn (không kể hai nguồn) là","o":["8","7","9","5"],"a":"7","h":"Các cực đại trên đoạn S1S2 ứng với hiệu đường đi kλ thỏa mãn −S1S2 < kλ < S1S2.","e":"Điều kiện cực đại trên đoạn nối hai nguồn: −12 < 3k < 12, tức −4 < k < 4, nên k nhận các giá trị −3, −2, −1, 0, 1, 2, 3: có 7 điểm cực đại.","t":"ly-lop11","g":11,"l":"thu-thach"},{"p":"Một con lắc lò xo có độ cứng k = 100 N/m dao động điều hoà với biên độ A = 10 cm. Cơ năng của con lắc là","o":["5 J","1 J","0,05 J","0,5 J"],"a":"0,5 J","h":"Cơ năng con lắc lò xo: W = ½kA². Nhớ đổi biên độ sang mét.","e":"Đổi A = 10 cm = 0,1 m. Cơ năng: W = ½kA² = ½ × 100 × (0,1)² = 0,5 J.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Một vật dao động điều hoà có cơ năng là W và biên độ A. Khi vật có li độ x = A/2 thì động năng của vật bằng","o":["W/4","W/2","3W/4","W/8"],"a":"3W/4","h":"Thế năng tại li độ x tỉ lệ với x²: Wt = W(x/A)², còn động năng bằng cơ năng trừ thế năng.","e":"Tại li độ x = A/2, thế năng Wt = W × (1/2)² = W/4. Động năng: Wđ = W − Wt = W − W/4 = 3W/4.","t":"ly-lop11","g":11,"l":"thu-thach"},{"p":"Một con lắc lò xo gồm vật nặng có khối lượng 1 kg gắn vào lò xo có độ cứng 40 N/m. Lấy π² = 10. Chu kì dao động của con lắc là","o":["0,5 s","2 s","1 s","0,25 s"],"a":"1 s","h":"Chu kì con lắc lò xo: T = 2π√(m/k).","e":"T = 2π√(m/k) = 2π√(1/40). Với π² = 10: T² = 4π²m/k = 4 × 10 × 1/40 = 1, suy ra T = 1 s.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Một con lắc đơn dao động nhỏ với chu kì 1 s tại nơi có gia tốc rơi tự do g = 10 m/s². Lấy π² = 10. Chiều dài dây treo của con lắc là","o":["25 cm","1 m","50 cm","2,5 cm"],"a":"25 cm","h":"Từ công thức chu kì con lắc đơn T = 2π√(l/g), suy ra l = gT²/(4π²).","e":"l = gT²/(4π²) = 10 × 1²/(4 × 10) = 0,25 m = 25 cm.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Một nguồn điện có suất điện động 10 V và điện trở trong 1 Ω được mắc với điện trở ngoài 4 Ω thành mạch kín. Hiệu suất của nguồn điện là","o":["75%","80%","20%","60%"],"a":"80%","h":"Hiệu suất nguồn điện: H = U/E = R/(R + r).","e":"Hiệu suất của nguồn: H = R/(R + r) = 4/(4 + 1) = 0,8 = 80%. Phần năng lượng còn lại (20%) hao phí do điện trở trong của nguồn.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Một nguồn điện có suất điện động 12 V. Khi nguồn hoạt động, trong mạch có dòng điện 0,5 A chạy qua trong thời gian 2 phút. Công của nguồn điện trong thời gian đó là","o":["720 J","360 J","1440 J","72 J"],"a":"720 J","h":"Công của nguồn điện: A = EIt. Nhớ đổi thời gian sang giây.","e":"Đổi t = 2 phút = 120 s. Công của nguồn điện: A = EIt = 12 × 0,5 × 120 = 720 J.","t":"ly-lop11","g":11,"l":"nhe-nhang"},{"p":"Điện áp xoay chiều giữa hai đầu một đoạn mạch có giá trị cực đại là 311 V. Giá trị hiệu dụng của điện áp này xấp xỉ bao nhiêu?","o":["220 V","311 V","155 V","440 V"],"a":"220 V","h":"Giá trị hiệu dụng bằng giá trị cực đại chia cho căn 2.","e":"U = U0 / 1,41 = 311 / 1,41 ≈ 220 V. Đây chính là điện áp 220 V quen thuộc của lưới điện sinh hoạt.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Dòng điện xoay chiều trong lưới điện sinh hoạt ở Việt Nam có tần số bằng bao nhiêu?","o":["60 Hz","50 Hz","25 Hz","100 Hz"],"a":"50 Hz","h":"Hãy nhớ tần số lưới điện của nước ta khác với một số nước dùng 60 Hz.","e":"Lưới điện Việt Nam có tần số 50 Hz, tức dòng điện đổi chiều 100 lần trong một giây.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Cường độ hiệu dụng của dòng điện xoay chiều được định nghĩa như thế nào?","o":["Bằng giá trị trung bình của cường độ tức thời trong một chu kì","Bằng giá trị cực đại của cường độ tức thời","Bằng cường độ của dòng điện không đổi gây ra cùng tác dụng nhiệt trong cùng một thời gian","Bằng cường độ tức thời tại thời điểm dòng điện đạt đỉnh"],"a":"Bằng cường độ của dòng điện không đổi gây ra cùng tác dụng nhiệt trong cùng một thời gian","h":"Giá trị hiệu dụng gắn với tác dụng nhiệt (công suất tỏa nhiệt) của dòng điện.","e":"Theo định nghĩa, I hiệu dụng là cường độ dòng điện không đổi mà khi qua cùng một điện trở trong cùng thời gian thì tỏa ra cùng một nhiệt lượng. Vì vậy I = I0 / 1,41.","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Một máy biến áp lí tưởng có cuộn sơ cấp 1 000 vòng, cuộn thứ cấp 100 vòng. Đặt vào cuộn sơ cấp điện áp hiệu dụng 220 V. Điện áp hiệu dụng ở cuộn thứ cấp là bao nhiêu?","o":["2 200 V","110 V","220 V","22 V"],"a":"22 V","h":"Dùng tỉ số U1/U2 = N1/N2 của máy biến áp.","e":"U2 = U1 × N2/N1 = 220 × 100/1 000 = 22 V. Đây là máy hạ áp vì cuộn thứ cấp ít vòng hơn.","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Máy biến áp hoạt động dựa trên hiện tượng vật lí nào?","o":["Hiện tượng quang điện","Hiện tượng cảm ứng điện từ","Hiện tượng nhiễm điện do cọ xát","Tác dụng phát sáng của dòng điện"],"a":"Hiện tượng cảm ứng điện từ","h":"Dòng điện biến thiên tạo từ trường biến thiên qua lõi thép.","e":"Dòng xoay chiều ở cuộn sơ cấp tạo từ thông biến thiên qua cuộn thứ cấp, làm xuất hiện suất điện động cảm ứng ở thứ cấp — đó là hiện tượng cảm ứng điện từ.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Khi truyền tải điện năng đi xa với cùng một công suất, biện pháp hiệu quả nhất để giảm hao phí do tỏa nhiệt trên đường dây là gì?","o":["Giảm điện áp ở nơi phát để đảm bảo an toàn","Tăng cường độ dòng điện truyền tải","Tăng điện áp ở nơi phát trước khi truyền tải","Dùng dây dẫn có điện trở suất lớn hơn"],"a":"Tăng điện áp ở nơi phát trước khi truyền tải","h":"Hao phí tỉ lệ với bình phương cường độ dòng điện trên dây.","e":"Hao phí Php = I²R. Với cùng công suất, tăng điện áp U lên thì I giảm, nên hao phí giảm theo bình phương điện áp — đây là biện pháp hiệu quả nhất.","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Khi truyền tải một công suất điện không đổi đi xa, nếu tăng điện áp truyền tải lên 2 lần (các điều kiện khác không đổi) thì công suất hao phí trên đường dây thay đổi thế nào?","o":["Giảm 2 lần","Giảm 8 lần","Không thay đổi","Giảm 4 lần"],"a":"Giảm 4 lần","h":"Hao phí tỉ lệ nghịch với bình phương điện áp truyền tải.","e":"Php tỉ lệ nghịch với U². U tăng 2 lần thì U² tăng 4 lần nên hao phí giảm 4 lần.","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Trong nhà máy điện, máy phát điện xoay chiều tạo ra dòng điện xoay chiều bằng cách nào?","o":["Cho cuộn dây quay trong từ trường (hoặc nam châm quay) để từ thông qua cuộn dây biến thiên","Đốt nóng dây dẫn cho đến khi phát điện","Dùng phản ứng hóa học như trong pin","Chiếu ánh sáng mạnh vào cuộn dây"],"a":"Cho cuộn dây quay trong từ trường (hoặc nam châm quay) để từ thông qua cuộn dây biến thiên","h":"Hãy nhớ nguyên tắc cảm ứng điện từ của Faraday.","e":"Khi khung dây quay trong từ trường, từ thông qua khung biến thiên tuần hoàn, sinh ra suất điện động cảm ứng xoay chiều — nguyên lí của mọi máy phát điện xoay chiều.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Trong mạch điện xoay chiều RLC mắc nối tiếp, hiện tượng cộng hưởng điện xảy ra khi nào?","o":["Tổng trở của mạch lớn nhất và cường độ dòng điện nhỏ nhất","Điện trở bằng cảm kháng của cuộn dây","Cảm kháng bằng dung kháng, tổng trở nhỏ nhất và cường độ hiệu dụng đạt giá trị lớn nhất","Mạch không tiêu thụ điện năng chút nào"],"a":"Cảm kháng bằng dung kháng, tổng trở nhỏ nhất và cường độ hiệu dụng đạt giá trị lớn nhất","h":"Ở cộng hưởng, hai thành phần kháng của cuộn cảm và tụ điện triệt tiêu nhau.","e":"Khi ZL = ZC, tổng trở Z = R là nhỏ nhất nên I = U/R đạt lớn nhất; dòng điện cùng pha với điện áp. Đó là hiện tượng cộng hưởng điện.","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Việc làm nào sau đây là an toàn khi sử dụng và sửa chữa điện xoay chiều trong gia đình?","o":["Dùng tay ướt chạm vào công tắc điện","Tiếp tục dùng dây điện đã bị hở lớp cách điện","Cắm thật nhiều thiết bị công suất lớn vào cùng một ổ cắm","Ngắt cầu dao (aptomat) trước khi sửa chữa thiết bị điện"],"a":"Ngắt cầu dao (aptomat) trước khi sửa chữa thiết bị điện","h":"Luôn cắt nguồn điện trước khi chạm vào thiết bị cần sửa.","e":"Ngắt cầu dao giúp cách li hoàn toàn nguồn điện, tránh bị điện giật khi sửa chữa. Tay ướt, dây hở cách điện và quá tải ổ cắm đều rất nguy hiểm.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Sắp xếp các loại sóng điện từ sau đây theo thứ tự tần số tăng dần, đúng là:","o":["Sóng vô tuyến, tia hồng ngoại, ánh sáng nhìn thấy, tia tử ngoại, tia X, tia gamma","Sóng vô tuyến, ánh sáng nhìn thấy, tia hồng ngoại, tia tử ngoại, tia X, tia gamma","Tia gamma, tia X, tia tử ngoại, ánh sáng nhìn thấy, tia hồng ngoại, sóng vô tuyến","Tia hồng ngoại, sóng vô tuyến, ánh sáng nhìn thấy, tia X, tia tử ngoại, tia gamma"],"a":"Sóng vô tuyến, tia hồng ngoại, ánh sáng nhìn thấy, tia tử ngoại, tia X, tia gamma","h":"Tần số tăng thì bước sóng giảm; sóng vô tuyến có tần số nhỏ nhất.","e":"Trong thang sóng điện từ, theo tần số tăng dần: sóng vô tuyến → hồng ngoại → ánh sáng nhìn thấy → tử ngoại → tia X → tia gamma.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Tia hồng ngoại được ứng dụng phổ biến trong trường hợp nào sau đây?","o":["Tiệt trùng dụng cụ y tế","Sưởi ấm và làm điều khiển từ xa (remote) cho tivi","Chụp X-quang để xem xương","Khử trùng nước uống"],"a":"Sưởi ấm và làm điều khiển từ xa (remote) cho tivi","h":"Tia hồng ngoại có tác dụng nhiệt mạnh.","e":"Tia hồng ngoại gây tác dụng nhiệt nên dùng để sưởi ấm, sấy khô; nó cũng được dùng trong remote điều khiển tivi, điều hòa. Tiệt trùng và khử trùng là việc của tia tử ngoại.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Tia tử ngoại (tia UV) thường được dùng để làm gì?","o":["Sưởi ấm phòng","Chụp ảnh xương trong cơ thể","Làm điều khiển từ xa cho tivi","Khử trùng, tiệt trùng dụng cụ y tế và nước"],"a":"Khử trùng, tiệt trùng dụng cụ y tế và nước","h":"Tia tử ngoại có khả năng diệt khuẩn.","e":"Tia tử ngoại có tác dụng sinh học mạnh, diệt được vi khuẩn nên dùng để tiệt trùng dụng cụ y tế, khử trùng nước và không khí; nó còn giúp phát hiện tiền giả.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Tia X được ứng dụng rộng rãi trong lĩnh vực nào sau đây?","o":["Chụp X-quang y tế và kiểm tra hành lí ở sân bay","Điều khiển tivi từ xa","Sưởi ấm, sấy khô sản phẩm","Nấu chín thức ăn trong lò vi sóng"],"a":"Chụp X-quang y tế và kiểm tra hành lí ở sân bay","h":"Tia X xuyên qua mô mềm nhưng bị xương hấp thụ mạnh.","e":"Nhờ khả năng đâm xuyên và bị xương hấp thụ mạnh hơn mô mềm, tia X dùng để chụp ảnh xương, răng; ở sân bay, tia X giúp kiểm tra hành lí mà không cần mở.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Phát biểu nào sau đây về tia gamma là đúng?","o":["Tia gamma có bước sóng dài nhất trong thang sóng điện từ","Tia gamma có bước sóng ngắn nhất và khả năng đâm xuyên mạnh nhất trong các sóng điện từ","Tia gamma là dòng hạt mang điện tích dương","Tia gamma chỉ phát ra từ các đèn sưởi hồng ngoại"],"a":"Tia gamma có bước sóng ngắn nhất và khả năng đâm xuyên mạnh nhất trong các sóng điện từ","h":"Tia gamma đứng ở cuối thang sóng điện từ, phía tần số cao nhất.","e":"Tia gamma có tần số lớn nhất, bước sóng ngắn nhất nên năng lượng photon lớn và đâm xuyên mạnh nhất; nó là sóng điện từ, không mang điện.","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Vì sao sóng vô tuyến được dùng trong truyền thông (radio, truyền hình, điện thoại di động)?","o":["Vì mắt thường nhìn thấy được sóng vô tuyến","Vì sóng vô tuyến không truyền được trong chân không","Vì sóng vô tuyến mang được thông tin và truyền đi xa trong không gian","Vì sóng vô tuyến có năng lượng lớn nhất trong các sóng điện từ"],"a":"Vì sóng vô tuyến mang được thông tin và truyền đi xa trong không gian","h":"Sóng điện từ truyền được trong chân không với tốc độ ánh sáng.","e":"Sóng vô tuyến có bước sóng dài, dễ dàng mang tín hiệu (nhờ điều chế) và lan truyền đi xa, kể cả trong chân không, nên là nền tảng của truyền thông không dây.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Một sóng vô tuyến có tần số 100 MHz truyền trong chân không với tốc độ 3×10^8 m/s. Bước sóng của sóng này là bao nhiêu?","o":["3 m","0,3 m","30 m","300 m"],"a":"3 m","h":"Dùng công thức bước sóng = tốc độ / tần số, chú ý đổi 100 MHz = 10^8 Hz.","e":"λ = c/f = 3×10^8 / 10^8 = 3 m.","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Hiện tượng quang điện ngoài là hiện tượng nào sau đây?","o":["Ánh sáng làm kim loại nóng lên rồi phát sáng","Dòng điện chạy qua kim loại làm kim loại phát sáng","Ánh sáng chiếu vào bề mặt kim loại làm bật các electron ra khỏi bề mặt đó","Ánh sáng bị bề mặt kim loại phản xạ hoàn toàn"],"a":"Ánh sáng chiếu vào bề mặt kim loại làm bật các electron ra khỏi bề mặt đó","h":"Hiện tượng này liên quan đến electron bị 'đánh bật' ra khỏi kim loại.","e":"Khi ánh sáng có tần số đủ lớn chiếu vào kim loại, các photon truyền năng lượng cho electron và làm chúng bật ra khỏi bề mặt — đó là hiện tượng quang điện ngoài, nền tảng của pin quang điện và cảm biến ánh sáng.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Năng lượng của một photon tỉ lệ với tần số của ánh sáng theo công thức E = hf. Nếu tần số ánh sáng tăng gấp đôi thì năng lượng của mỗi photon thay đổi thế nào?","o":["Tăng gấp bốn lần","Tăng gấp đôi","Giảm đi một nửa","Không thay đổi"],"a":"Tăng gấp đôi","h":"Năng lượng photon tỉ lệ thuận với tần số.","e":"Vì E = hf nên khi f tăng gấp đôi, E cũng tăng gấp đôi. Photon tần số càng cao (như tia X, tia gamma) càng mang năng lượng lớn.","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Một photon có tần số f = 6×10^14 Hz. Biết hằng số Planck h = 6,63×10^-34 J·s. Năng lượng của photon này xấp xỉ bằng bao nhiêu?","o":["4×10^-20 J","4×10^-18 J","1,1×10^-27 J","4×10^-19 J"],"a":"4×10^-19 J","h":"Thay số trực tiếp vào công thức E = hf.","e":"E = hf = 6,63×10^-34 × 6×10^14 ≈ 39,8×10^-20 ≈ 4×10^-19 J.","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Tia laser được ứng dụng trong trường hợp nào sau đây?","o":["Sưởi ấm thức ăn trong lò vi sóng","Chụp X-quang xương","Phẫu thuật mắt và truyền thông tin bằng cáp quang","Tiệt trùng dụng cụ y tế"],"a":"Phẫu thuật mắt và truyền thông tin bằng cáp quang","h":"Laser là chùm sáng rất định hướng và đơn sắc.","e":"Tia laser có tính định hướng cao, đơn sắc và cường độ tập trung nên dùng trong phẫu thuật mắt, cắt khắc vật liệu, đo khoảng cách và truyền tín hiệu trong cáp quang.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Hạt nhân nguyên tử được cấu tạo từ những hạt nào?","o":["Proton và electron","Proton và neutron","Electron và neutron","Chỉ gồm các proton"],"a":"Proton và neutron","h":"Các hạt trong hạt nhân được gọi chung là nuclôn.","e":"Hạt nhân gồm proton (mang điện dương) và neutron (không mang điện); hai loại hạt này gọi chung là nuclôn. Electron chuyển động xung quanh hạt nhân, không nằm trong hạt nhân.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Hạt nhân urani U-235 có số hiệu nguyên tử Z = 92 và số khối A = 235. Số neutron trong hạt nhân này là bao nhiêu?","o":["143","92","235","327"],"a":"143","h":"Số neutron bằng số khối trừ đi số proton.","e":"N = A − Z = 235 − 92 = 143 neutron. Hạt nhân U-235 là nhiên liệu phổ biến trong nhà máy điện hạt nhân.","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Các đồng vị của cùng một nguyên tố hóa học là những hạt nhân có đặc điểm gì?","o":["Cùng số khối nhưng khác số proton","Cùng số neutron nhưng khác số proton","Khác nhau cả số proton và số electron trong hạt nhân","Cùng số proton nhưng khác số neutron"],"a":"Cùng số proton nhưng khác số neutron","h":"Đồng vị vẫn thuộc cùng một nguyên tố nên tính chất hóa học giống nhau.","e":"Đồng vị có cùng Z (cùng số proton, cùng vị trí trong bảng tuần hoàn) nhưng khác số neutron nên khác số khối A, ví dụ cacbon-12 và cacbon-14.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Phát biểu nào sau đây về tia phóng xạ alpha (α) là đúng?","o":["Tia α là sóng điện từ có khả năng đâm xuyên mạnh nhất","Tia α là hạt nhân heli, khả năng đâm xuyên yếu, một tờ giấy cũng chặn được","Tia α là dòng electron chuyển động nhanh","Tia α xuyên qua được tấm chì dày dễ dàng"],"a":"Tia α là hạt nhân heli, khả năng đâm xuyên yếu, một tờ giấy cũng chặn được","h":"Tia α là tia phóng xạ 'yếu' nhất về khả năng đâm xuyên.","e":"Tia α gồm 2 proton và 2 neutron (hạt nhân heli), mang điện dương, ion hóa mạnh nhưng đâm xuyên yếu — chỉ cần tờ giấy hoặc lớp da ngoài là chặn được. Dòng electron là tia β.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Sắp xếp các tia phóng xạ theo thứ tự khả năng đâm xuyên tăng dần, đúng là:","o":["γ, β, α","β, α, γ","α, γ, β","α, β, γ"],"a":"α, β, γ","h":"Tia gamma là sóng điện từ nên đâm xuyên mạnh nhất.","e":"Khả năng đâm xuyên: tia α yếu nhất (giấy chặn được), tia β trung bình (cần tấm nhôm mỏng), tia γ mạnh nhất (cần tấm chì dày mới chặn bớt).","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Một chất phóng xạ có chu kì bán rã là 5 ngày. Ban đầu có một lượng chất nhất định. Sau 10 ngày, lượng chất phóng xạ còn lại bằng bao nhiêu phần lượng ban đầu?","o":["1/2","1/8","1/4","1/16"],"a":"1/4","h":"10 ngày ứng với bao nhiêu chu kì bán rã? Mỗi chu kì, lượng chất giảm một nửa.","e":"10 ngày = 2 chu kì bán rã. Sau mỗi chu kì lượng chất còn một nửa: sau 2 chu kì còn (1/2)² = 1/4 lượng ban đầu.","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Phản ứng phân hạch là phản ứng hạt nhân trong đó:","o":["Một hạt nhân rất nặng vỡ thành hai hạt nhân nhẹ hơn, kèm theo neutron và tỏa năng lượng","Hai hạt nhân nhẹ kết hợp thành một hạt nhân nặng hơn","Một hạt nhân tự phát ra tia gamma","Một hạt nhân hấp thụ một electron từ lớp vỏ"],"a":"Một hạt nhân rất nặng vỡ thành hai hạt nhân nhẹ hơn, kèm theo neutron và tỏa năng lượng","h":"Phân hạch là 'chia tách' hạt nhân nặng như urani-235.","e":"Trong phản ứng phân hạch, hạt nhân nặng (như U-235) hấp thụ neutron rồi vỡ thành hai hạt nhân nhẹ hơn, giải phóng thêm neutron và năng lượng lớn — nguyên lí của nhà máy điện hạt nhân.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Nguồn năng lượng chính của Mặt Trời đến từ loại phản ứng hạt nhân nào?","o":["Phản ứng phân hạch urani","Sự đốt cháy than và khí đốt","Phóng xạ alpha của các nguyên tố nặng","Phản ứng nhiệt hạch (tổng hợp hạt nhân nhẹ)"],"a":"Phản ứng nhiệt hạch (tổng hợp hạt nhân nhẹ)","h":"Trong lòng Mặt Trời, các hạt nhân hiđrô kết hợp tạo thành heli.","e":"Ở nhiệt độ hàng chục triệu độ trong lòng Mặt Trời, các hạt nhân nhẹ (hiđrô) tổng hợp thành hạt nhân nặng hơn (heli) và tỏa năng lượng khổng lồ — đó là phản ứng nhiệt hạch.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Năng lượng liên kết của một hạt nhân là gì?","o":["Tổng động năng của các electron quanh hạt nhân","Năng lượng tối thiểu cần cung cấp để phá vỡ hạt nhân thành các proton và neutron riêng rẽ","Năng lượng mà hạt nhân tỏa ra dưới dạng tia gamma khi phóng xạ","Năng lượng cần để ion hóa nguyên tử"],"a":"Năng lượng tối thiểu cần cung cấp để phá vỡ hạt nhân thành các proton và neutron riêng rẽ","h":"Năng lượng liên kết gắn với việc 'giữ' các nuclôn lại với nhau trong hạt nhân.","e":"Muốn tách hạt nhân thành từng nuclôn riêng rẽ phải cung cấp một năng lượng ít nhất bằng năng lượng liên kết. Ngược lại, khi các nuclôn kết hợp tạo thành hạt nhân, năng lượng này được tỏa ra.","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Đồng vị phóng xạ được ứng dụng trong y học như thế nào?","o":["Dùng để chẩn đoán bệnh và điều trị (xạ trị) một số bệnh ung thư","Dùng để sưởi ấm phòng bệnh","Dùng làm thuốc nhuộm trong chụp ảnh thông thường","Dùng để thắp sáng bóng đèn trong bệnh viện"],"a":"Dùng để chẩn đoán bệnh và điều trị (xạ trị) một số bệnh ung thư","h":"Hãy nghĩ đến các kĩ thuật 'y học hạt nhân' ở bệnh viện.","e":"Y học hạt nhân dùng đồng vị phóng xạ để ghi hình chẩn đoán (ví dụ xạ hình tuyến giáp) và dùng tia phóng xạ chiếu tập trung để tiêu diệt tế bào ung thư trong xạ trị.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Trong các kĩ thuật chẩn đoán hình ảnh sau đây, kĩ thuật nào KHÔNG sử dụng bức xạ ion hóa?","o":["Chụp X-quang","Chụp cắt lớp vi tính (CT)","Chụp cộng hưởng từ (MRI)","Xạ hình bằng đồng vị phóng xạ"],"a":"Chụp cộng hưởng từ (MRI)","h":"MRI dùng từ trường và sóng vô tuyến, còn sóng vô tuyến không gây ion hóa.","e":"MRI dùng từ trường mạnh và sóng vô tuyến để tạo hình ảnh, không dùng tia X hay tia gamma nên không có bức xạ ion hóa. Siêu âm cũng là kĩ thuật không dùng bức xạ ion hóa.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Cáp quang được dùng rộng rãi trong mạng Internet nhờ đặc điểm nào?","o":["Truyền tín hiệu bằng ánh sáng với tốc độ cao và hao hụt ít","Truyền dòng điện mạnh hơn dây đồng","Truyền tín hiệu bằng sóng âm trong sợi thủy tinh","Truyền tia X mang dữ liệu đi xa"],"a":"Truyền tín hiệu bằng ánh sáng với tốc độ cao và hao hụt ít","h":"Tín hiệu trong cáp quang là các xung ánh sáng phản xạ toàn phần trong sợi quang.","e":"Cáp quang dẫn ánh sáng mang thông tin đi rất xa với tốc độ cao, ít suy hao và không bị nhiễu điện từ, nên là xương sống của Internet và viễn thông hiện nay.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Để bảo vệ cơ thể khỏi tác hại của bức xạ phóng xạ, bộ ba biện pháp cơ bản là gì?","o":["Đeo khẩu trang vải, đứng gần nguồn để quan sát rõ và tiếp xúc lâu","Chỉ cần đứng xa nguồn, không cần che chắn và không cần để ý thời gian","Giảm thời gian tiếp xúc, tăng khoảng cách tới nguồn và dùng vật liệu che chắn phù hợp","Cầm nguồn phóng xạ bằng tay không trong thời gian ngắn"],"a":"Giảm thời gian tiếp xúc, tăng khoảng cách tới nguồn và dùng vật liệu che chắn phù hợp","h":"Ba yếu tố: thời gian — khoảng cách — che chắn.","e":"Nguyên tắc an toàn bức xạ: ở gần nguồn càng ngắn càng tốt, càng xa nguồn bức xạ càng yếu, và dùng vật liệu che chắn thích hợp (như chì với tia X, tia gamma) để giảm liều bức xạ.","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Một tấm pin mặt trời nhận được công suất ánh sáng 800 W và có hiệu suất chuyển đổi 20%. Công suất điện mà tấm pin tạo ra là bao nhiêu?","o":["40 W","160 W","320 W","800 W"],"a":"160 W","h":"Công suất điện bằng hiệu suất nhân với công suất ánh sáng nhận được.","e":"P điện = 20% × 800 W = 0,2 × 800 = 160 W. Pin mặt trời chuyển trực tiếp quang năng thành điện năng nhờ hiện tượng quang điện.","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Nước đá đang tan ở 0 °C là quá trình chuyển thể nào, và trong quá trình này nước đá thu nhiệt hay toả nhiệt?","o":["Quá trình đông đặc, toả nhiệt","Quá trình nóng chảy, thu nhiệt","Quá trình hoá hơi, thu nhiệt","Quá trình ngưng tụ, toả nhiệt"],"a":"Quá trình nóng chảy, thu nhiệt","h":"Nước đá là thể rắn, nước lỏng là thể lỏng.","e":"Nước đá chuyển từ thể rắn sang thể lỏng nên đó là quá trình nóng chảy. Muốn nóng chảy, vật phải thu nhiệt từ môi trường xung quanh.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Nội năng của một vật có thể thay đổi bằng hai cách nào sau đây?","o":["Chỉ bằng cách truyền nhiệt qua dẫn nhiệt","Chỉ bằng cách thực hiện công cơ học","Bằng cách thực hiện công hoặc truyền nhiệt","Bằng cách thay đổi khối lượng của vật"],"a":"Bằng cách thực hiện công hoặc truyền nhiệt","h":"Nghĩ tới việc cọ xát hai bàn tay và việc hơ vật trên lửa.","e":"Có hai cách làm thay đổi nội năng: thực hiện công (ví dụ cọ xát hai bàn tay làm tay nóng lên) và truyền nhiệt (ví dụ hơ vật trên lửa làm vật nóng lên).","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Theo định luật I của nhiệt động lực học, ΔU = A + Q. Nếu một hệ vừa nhận công (A > 0) vừa nhận nhiệt (Q > 0) từ bên ngoài thì nội năng của hệ thay đổi thế nào?","o":["Nội năng tăng","Nội năng giảm","Nội năng không đổi","Không đủ dữ kiện để kết luận"],"a":"Nội năng tăng","h":"Cả A và Q đều dương, hãy xét dấu của tổng A + Q.","e":"ΔU = A + Q. Hệ nhận công nên A > 0, hệ nhận nhiệt nên Q > 0, do đó ΔU > 0, tức nội năng của hệ tăng.","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Nhiệt độ 27 °C tương ứng với bao nhiêu kelvin (K) trong thang nhiệt độ tuyệt đối?","o":["246 K","273 K","327 K","300 K"],"a":"300 K","h":"Dùng công thức T(K) = t(°C) + 273.","e":"T = t + 273 = 27 + 273 = 300 K.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Nhiệt dung riêng của nước là 4200 J/kg.K. Nhiệt lượng cần cung cấp để đun nóng 2 kg nước tăng thêm 10 °C là bao nhiêu?","o":["8 400 J","84 000 J","840 000 J","42 000 J"],"a":"84 000 J","h":"Áp dụng công thức Q = mcΔt.","e":"Q = mcΔt = 2 × 4200 × 10 = 84 000 J.","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Nhiệt nóng chảy riêng của nước đá là 3,4×10^5 J/kg. Để làm nóng chảy hoàn toàn 0,5 kg nước đá ở 0 °C (nhiệt độ nóng chảy) cần cung cấp nhiệt lượng bao nhiêu?","o":["3,4×10^5 J","6,8×10^5 J","1,7×10^5 J","1,7×10^4 J"],"a":"1,7×10^5 J","h":"Nhiệt lượng nóng chảy tính bằng Q = λm.","e":"Q = λm = 3,4×10^5 × 0,5 = 1,7×10^5 J. Đây là nhiệt lượng cần để phá vỡ liên kết trong nước đá ở đúng nhiệt độ nóng chảy, nhiệt độ của vật không tăng trong quá trình này.","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Ở cùng nhiệt độ 100 °C, hơi nước thường gây bỏng nặng hơn nước sôi. Nguyên nhân chính là gì?","o":["Khi ngưng tụ trên da, hơi nước toả thêm nhiệt lượng hoá hơi nên da nhận nhiều nhiệt hơn","Hơi nước có nhiệt độ cao hơn nước sôi","Hơi nước chứa nhiều năng lượng bức xạ hơn nước sôi","Hơi nước truyền nhiệt qua đối lưu nhanh hơn nước sôi"],"a":"Khi ngưng tụ trên da, hơi nước toả thêm nhiệt lượng hoá hơi nên da nhận nhiều nhiệt hơn","h":"Khi hơi nước chạm vào da, nó chuyển thành nước lỏng.","e":"Hơi nước và nước sôi cùng ở 100 °C, nhưng khi chạm vào da, hơi nước trước hết ngưng tụ thành nước lỏng và toả ra nhiệt lượng hoá hơi, sau đó lượng nước 100 °C đó tiếp tục toả nhiệt. Vì vậy da nhận nhiều nhiệt hơn so với chỉ tiếp xúc nước sôi, bỏng nặng hơn.","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Theo thuyết động học phân tử, phát biểu nào sau đây đúng về các phân tử cấu tạo nên chất?","o":["Các phân tử đứng yên khi vật không chuyển động","Các phân tử chỉ chuyển động khi vật được đun nóng","Nhiệt độ càng thấp, các phân tử chuyển động càng nhanh","Các phân tử chuyển động không ngừng và nhiệt độ càng cao chúng chuyển động càng nhanh"],"a":"Các phân tử chuyển động không ngừng và nhiệt độ càng cao chúng chuyển động càng nhanh","h":"Chuyển động của các phân tử được gọi là chuyển động nhiệt.","e":"Các phân tử cấu tạo nên chất luôn chuyển động hỗn loạn không ngừng (chuyển động nhiệt), ngay cả khi vật đứng yên. Nhiệt độ càng cao, các phân tử chuyển động càng nhanh.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Theo mô hình động học phân tử chất khí, các phân tử khí chuyển động như thế nào?","o":["Chuyển động theo quỹ đạo tròn đều quanh thành bình","Chuyển động hỗn loạn, không ngừng theo mọi hướng và va chạm đàn hồi với nhau và với thành bình","Chỉ dao động quanh một vị trí cân bằng cố định","Chuyển động thẳng đều cùng một hướng với tốc độ bằng nhau"],"a":"Chuyển động hỗn loạn, không ngừng theo mọi hướng và va chạm đàn hồi với nhau và với thành bình","h":"Chuyển động của phân tử khí khác với phân tử chất rắn ở chỗ chúng không bị giữ quanh một vị trí cố định.","e":"Theo mô hình động học phân tử, các phân tử khí chuyển động hỗn loạn không ngừng theo mọi hướng, giữa hai lần va chạm chúng chuyển động thẳng đều, và các va chạm với nhau cũng như với thành bình đều là đàn hồi.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Một lượng khí lí tưởng được nén đẳng nhiệt (nhiệt độ không đổi) sao cho thể tích giảm còn một nửa. Áp suất của khối khí thay đổi thế nào?","o":["Giảm còn một nửa","Không thay đổi","Tăng gấp đôi","Tăng gấp bốn"],"a":"Tăng gấp đôi","h":"Theo định luật Boyle, ở nhiệt độ không đổi pV = hằng số.","e":"Quá trình đẳng nhiệt tuân theo định luật Boyle: pV = hằng số, nên áp suất tỉ lệ nghịch với thể tích. Thể tích giảm còn một nửa (V/2) thì áp suất tăng gấp đôi.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Một lượng khí lí tưởng ở áp suất 1 atm chiếm thể tích 6 lít. Nén đẳng nhiệt khối khí này đến khi thể tích còn 2 lít. Áp suất của khí sau khi nén là bao nhiêu?","o":["2 atm","12 atm","1,5 atm","3 atm"],"a":"3 atm","h":"Dùng định luật Boyle: p₁V₁ = p₂V₂.","e":"Vì quá trình là đẳng nhiệt nên p₁V₁ = p₂V₂, suy ra p₂ = p₁V₁/V₂ = 1 × 6/2 = 3 atm.","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Một lượng khí lí tưởng được đun nóng đẳng áp từ 27 °C lên 327 °C. Thể tích ban đầu của khí là 6 lít. Thể tích của khí sau khi đun nóng là bao nhiêu?","o":["12 lít","9 lít","72 lít","3 lít"],"a":"12 lít","h":"Theo định luật Charles, V tỉ lệ thuận với nhiệt độ tuyệt đối T; nhớ đổi nhiệt độ sang kelvin trước khi tính.","e":"Đổi sang thang tuyệt đối: T₁ = 27 + 273 = 300 K, T₂ = 327 + 273 = 600 K. Quá trình đẳng áp tuân theo định luật Charles: V₂ = V₁ × T₂/T₁ = 6 × 600/300 = 12 lít. Lưu ý không được lấy tỉ lệ theo độ C.","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Một lượng khí lí tưởng có trạng thái ban đầu: áp suất 1 atm, thể tích 10 lít, nhiệt độ 300 K. Sau khi biến đổi, áp suất là 2 atm và thể tích vẫn là 10 lít. Nhiệt độ của khí lúc sau là bao nhiêu?","o":["150 K","600 K","300 K","450 K"],"a":"600 K","h":"Dùng phương trình trạng thái: p₁V₁/T₁ = p₂V₂/T₂.","e":"Từ phương trình trạng thái p₁V₁/T₁ = p₂V₂/T₂, ta có T₂ = p₂V₂T₁/(p₁V₁) = 2 × 10 × 300/(1 × 10) = 600 K.","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Động năng trung bình của chuyển động nhiệt của các phân tử khí lí tưởng phụ thuộc vào nhiệt độ như thế nào?","o":["Tỉ lệ nghịch với nhiệt độ tuyệt đối T","Chỉ phụ thuộc vào áp suất của khí","Tỉ lệ thuận với nhiệt độ tuyệt đối T","Không phụ thuộc vào nhiệt độ"],"a":"Tỉ lệ thuận với nhiệt độ tuyệt đối T","h":"Nhớ công thức động năng trung bình W = (3/2)kT.","e":"Động năng trung bình của chuyển động nhiệt của mỗi phân tử là W = (3/2)kT, trong đó k là hằng số Boltzmann và T là nhiệt độ tuyệt đối. Vậy động năng trung bình tỉ lệ thuận với nhiệt độ tuyệt đối.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Khi đun nóng một bình kín chứa khí (thể tích không đổi), áp suất của khí tăng lên. Theo mô hình động học phân tử, nguyên nhân là gì?","o":["Các phân tử khí nở ra, chiếm thể tích lớn hơn","Số phân tử khí trong bình tăng lên khi đun nóng","Khối lượng của mỗi phân tử khí tăng lên","Các phân tử chuyển động nhanh hơn, va chạm vào thành bình mạnh hơn và thường xuyên hơn"],"a":"Các phân tử chuyển động nhanh hơn, va chạm vào thành bình mạnh hơn và thường xuyên hơn","h":"Áp suất khí sinh ra do các phân tử va chạm vào thành bình.","e":"Áp suất khí là do các phân tử va chạm vào thành bình gây ra. Khi nhiệt độ tăng, các phân tử chuyển động nhanh hơn, nên va chạm vào thành bình mạnh hơn và với tần suất lớn hơn, làm áp suất tăng (số phân tử và khối lượng mỗi phân tử không đổi).","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Ở bên ngoài một thanh nam châm thẳng, các đường sức từ có chiều như thế nào?","o":["Đi ra từ cực Nam và đi vào cực Bắc của thanh nam châm","Đi ra từ cực Bắc và đi vào cực Nam của thanh nam châm","Chỉ xuất phát từ cực Bắc, không đi vào cực Nam","Luôn là những đường thẳng song song cách đều nhau"],"a":"Đi ra từ cực Bắc và đi vào cực Nam của thanh nam châm","h":"Hãy nhớ quy ước chiều đường sức từ và cách kim nam châm nhỏ định hướng trên đường sức.","e":"Theo quy ước, ở bên ngoài thanh nam châm, các đường sức từ đi ra từ cực Bắc (N) và đi vào cực Nam (S); ở bên trong nam châm, đường sức từ đi từ cực Nam sang cực Bắc, tạo thành những đường cong khép kín.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Các đường sức từ của từ trường do dòng điện thẳng dài gây ra có dạng","o":["các đường thẳng song song với dây dẫn","các đường tròn đồng tâm nằm trong mặt phẳng vuông góc với dây dẫn","các đường thẳng đi từ dây dẫn hướng ra xa theo mọi hướng","các đường cong khép kín đi qua lòng dây dẫn"],"a":"các đường tròn đồng tâm nằm trong mặt phẳng vuông góc với dây dẫn","h":"Hãy nhớ quy tắc nắm tay phải dùng để xác định chiều đường sức từ quanh dây dẫn thẳng.","e":"Từ trường của dòng điện thẳng dài có các đường sức là những đường tròn đồng tâm với tâm nằm trên dây dẫn, thuộc mặt phẳng vuông góc với dây. Chiều của đường sức từ được xác định bằng quy tắc nắm tay phải: ngón tay cái chỉ chiều dòng điện, các ngón tay khum lại chỉ chiều đường sức từ.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Độ lớn của lực từ tác dụng lên một đoạn dây dẫn thẳng mang dòng điện đặt trong từ trường đều phụ thuộc vào những yếu tố nào sau đây?","o":["Chỉ phụ thuộc vào cường độ dòng điện chạy qua dây","Chỉ phụ thuộc vào chiều dài của đoạn dây dẫn","Cảm ứng từ, cường độ dòng điện, chiều dài đoạn dây và góc giữa dây dẫn với đường sức từ","Điện trở và tiết diện của dây dẫn"],"a":"Cảm ứng từ, cường độ dòng điện, chiều dài đoạn dây và góc giữa dây dẫn với đường sức từ","h":"Lực từ có độ lớn F = BIl·sinα, hãy nhìn vào các đại lượng xuất hiện trong công thức.","e":"Độ lớn lực từ là F = BIl·sinα nên phụ thuộc vào cảm ứng từ B, cường độ dòng điện I, chiều dài đoạn dây l và góc α giữa dây với đường sức từ. Chiều của lực từ được xác định bằng quy tắc bàn tay trái.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Một diện tích S được đặt trong từ trường đều có cảm ứng từ B. Từ thông Φ qua diện tích S đạt giá trị lớn nhất khi góc α giữa vectơ cảm ứng từ và vectơ pháp tuyến của diện tích bằng","o":["0°","45°","90°","180°"],"a":"0°","h":"Từ thông được tính bằng Φ = BS·cosα, hãy xét khi nào cosα lớn nhất.","e":"Từ thông Φ = BS·cosα nên đạt giá trị lớn nhất Φ = BS khi cosα = 1, tức α = 0° (đường sức từ vuông góc với mặt diện tích S). Đơn vị của từ thông là vêbe (Wb).","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Dòng điện cảm ứng xuất hiện trong một mạch điện kín khi","o":["mạch được đặt trong một từ trường rất mạnh","mạch đứng yên trong từ trường đều không đổi","có đường sức từ xuyên qua mạch nhưng từ thông qua mạch không thay đổi","từ thông qua mạch kín đó biến thiên theo thời gian"],"a":"từ thông qua mạch kín đó biến thiên theo thời gian","h":"Điều kiện cần là số đường sức từ xuyên qua mạch phải thay đổi.","e":"Hiện tượng cảm ứng điện từ: khi từ thông qua một mạch kín biến thiên thì trong mạch xuất hiện dòng điện cảm ứng. Theo định luật Lenz, dòng điện cảm ứng có chiều sao cho từ trường của nó chống lại sự biến thiên của từ thông đã sinh ra nó.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Từ thông qua một vòng dây dẫn biến thiên đều từ 0,6 Wb xuống còn 0,2 Wb trong khoảng thời gian 0,2 s. Độ lớn của suất điện động cảm ứng xuất hiện trong vòng dây là","o":["0,08 V","2 V","0,5 V","4 V"],"a":"2 V","h":"Áp dụng công thức e = |ΔΦ/Δt|, trước hết hãy tính độ biến thiên từ thông.","e":"Độ biến thiên từ thông: |ΔΦ| = |0,2 − 0,6| = 0,4 Wb. Suất điện động cảm ứng: e = |ΔΦ/Δt| = 0,4/0,2 = 2 V.","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Một hạt nhân có số khối A = 30 và năng lượng liên kết là 240 MeV. Năng lượng liên kết riêng của hạt nhân này bằng bao nhiêu?","o":["240 MeV/nucleon","8 MeV/nucleon","30 MeV/nucleon","7200 MeV/nucleon"],"a":"8 MeV/nucleon","h":"Năng lượng liên kết riêng = năng lượng liên kết chia cho số khối A.","e":"Năng lượng liên kết riêng ε = E_lk/A = 240/30 = 8 MeV/nucleon. Đại lượng này đặc trưng cho mức độ bền vững của hạt nhân.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Hạt nhân radi Ra-226 (số proton Z = 88) phân rã alpha theo phương trình: Ra-226 → X + He-4 (hạt alpha có Z = 2). Hạt nhân X có số khối và số proton là bao nhiêu?","o":["Số khối 222, số proton 86","Số khối 222, số proton 88","Số khối 230, số proton 90","Số khối 220, số proton 84"],"a":"Số khối 222, số proton 86","h":"Áp dụng định luật bảo toàn số khối và bảo toàn điện tích (số proton) cho hai vế.","e":"Bảo toàn số khối: A_X = 226 − 4 = 222. Bảo toàn điện tích: Z_X = 88 − 2 = 86. Vậy X là hạt nhân radon Rn-222.","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Một mẫu chất phóng xạ ban đầu có khối lượng 80 g. Sau thời gian bằng 3 chu kì bán rã, khối lượng chất phóng xạ còn lại trong mẫu là bao nhiêu?","o":["20 g","26,7 g","10 g","40 g"],"a":"10 g","h":"Sau mỗi chu kì bán rã, khối lượng còn lại giảm đi một nửa.","e":"Sau 3 chu kì bán rã, khối lượng còn lại là m = 80/2³ = 80/8 = 10 g.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Một khối khí nhận nhiệt lượng Q = 500 J từ bên ngoài, đồng thời bị nén bởi ngoại lực thực hiện công A = 200 J lên khối khí. Độ biến thiên nội năng của khối khí bằng bao nhiêu?","o":["300 J","−300 J","1000 J","700 J"],"a":"700 J","h":"Dùng định luật I: ΔU = A + Q, với A và Q đều là các đại lượng hệ nhận vào.","e":"Khí nhận cả công (A = 200 J) và nhiệt (Q = 500 J) nên ΔU = A + Q = 200 + 500 = 700 J, nội năng của khí tăng 700 J.","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Trộn 200 g nước ở 80 °C với 200 g nước ở 20 °C trong một bình cách nhiệt, bỏ qua mọi hao phí nhiệt. Nhiệt độ của nước khi cân bằng nhiệt là bao nhiêu?","o":["60 °C","50 °C","40 °C","100 °C"],"a":"50 °C","h":"Hai lượng nước bằng nhau và cùng chất nên nhiệt độ cân bằng là trung bình cộng của hai nhiệt độ đầu.","e":"Khi cân bằng: m·c·(80 − t) = m·c·(t − 20) → 80 − t = t − 20 → t = 50 °C.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Đưa cực Bắc của một nam châm thẳng tiến lại gần một vòng dây dẫn kín. Theo định luật Lenz, dòng điện cảm ứng trong vòng dây có chiều sao cho mặt của vòng dây phía đối diện với nam châm trở thành cực nào?","o":["Cực Bắc, để đẩy nam châm ra xa","Cực Nam, để hút nam châm lại gần","Không trở thành cực nào vì vòng dây không phải nam châm","Lúc là cực Bắc, lúc là cực Nam tuỳ tốc độ đưa nam châm"],"a":"Cực Bắc, để đẩy nam châm ra xa","h":"Theo định luật Lenz, dòng điện cảm ứng luôn có tác dụng chống lại nguyên nhân sinh ra nó.","e":"Nguyên nhân sinh ra dòng cảm ứng là nam châm tiến lại gần làm từ thông tăng. Dòng cảm ứng làm mặt vòng dây đối diện trở thành cực Bắc, cùng dấu với cực nam châm đang tiến đến, tạo lực đẩy chống lại chuyển động đó.","t":"ly-lop12","g":12,"l":"thu-thach"},{"p":"Thiết bị nào sau đây hoạt động chủ yếu dựa trên tác dụng nhiệt của dòng điện xoáy (dòng Foucault) sinh ra do hiện tượng cảm ứng điện từ?","o":["Đèn sợi đốt","Quạt điện","Bếp từ","Bình nóng lạnh dùng dây điện trở"],"a":"Bếp từ","h":"Thiết bị này làm nóng trực tiếp đáy nồi bằng từ trường biến thiên, không dùng ngọn lửa hay dây đốt.","e":"Bếp từ tạo từ trường biến thiên, sinh dòng điện xoáy trong đáy nồi bằng kim loại; dòng xoáy này toả nhiệt làm chín thức ăn. Đây là ứng dụng tiêu biểu của dòng Foucault.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Một mạch điện xoay chiều RLC mắc nối tiếp có điện trở thuần R = 30 Ω, cảm kháng ZL = 50 Ω và dung kháng ZC = 10 Ω. Tổng trở của mạch bằng bao nhiêu?","o":["70 Ω","50 Ω","90 Ω","40 Ω"],"a":"50 Ω","h":"Tổng trở Z = √(R² + (ZL − ZC)²).","e":"Z = √(30² + (50 − 10)²) = √(900 + 1600) = √2500 = 50 Ω.","t":"ly-lop12","g":12,"l":"nhe-nhang"},{"p":"Một đoạn mạch xoay chiều có điện áp hiệu dụng U = 220 V, cường độ dòng điện hiệu dụng I = 2 A và hệ số công suất cosφ = 0,8. Công suất tiêu thụ của đoạn mạch bằng bao nhiêu?","o":["440 W","550 W","176 W","352 W"],"a":"352 W","h":"Công suất tiêu thụ của mạch xoay chiều: P = U·I·cosφ.","e":"P = U·I·cosφ = 220 × 2 × 0,8 = 352 W.","t":"ly-lop12","g":12,"l":"nhe-nhang"}];